/* Exam 3 flashcards: every idea of Lectures 20-33 as a card, in six piles: what a thing is, a derivation in three lines,
   the formulas you must carry (each card says whether the formula sheet has it), what changes when you change one
   thing, signs and directions, and numbers to know without a calculator. Drilled by E3Drill.cards (js/e3-drill.js):
   Leitner boxes kept in this browser. A second, hidden lesson lists every card with its answer, for reading and printing.
   A card is { id, cat, t, figHtml?, q, a, why, ex? }; ex = { expr, vars } lets the reader type the formula first. */
(function () {
  'use strict';
  const { R, RF } = C;

  // short pile names for the chips (three rows on a phone); the reading page uses the long ones as headings
  const CATS = { def: 'What is it?', derive: 'Derive it', recall: 'Formulas to carry', 'what-if': 'What if…', sign: 'Signs', numbers: 'Numbers' };
  const LONG = {
    def: 'What is it?',
    derive: 'Derive it in three lines',
    recall: 'Formulas to carry (and which are on the sheet)',
    'what-if': 'What if you change one thing?',
    sign: 'Signs and directions',
    numbers: 'Numbers without a calculator',
  };

  // ---------------------------------------------------------------- figures (front-of-card pictures that ask, never tell)
  // a current sheet seen edge-on: z to the right, y up, so x (and the current) points into the page
  function sheetFig() {
    const g = PF.fig({ alt: 'a current sheet seen edge-on in the plane z = 0, carrying current along x, into the page; z points right and y points up' });
    g.line(170, 18, 170, 182, { cls: 'thick dash' });
    for (const y of [48, 100, 152]) g.otimes(170, y, 8);
    g.label(184, 48, '\\mathbf J_s', 'l');
    g.label(90, 100, 'z<0', 'c');
    g.label(258, 100, 'z>0', 'c');
    g.label(170, 196, 'z=0', 't', 'small');
    g.arrow(34, 214, 84, 214, { hs: 6 });
    g.label(88, 214, 'z', 'l', 'small');
    g.arrow(34, 214, 34, 168, { hs: 6 });
    g.label(34, 162, 'y', 'b', 'small');
    g.otimes(34, 214, 5);
    g.label(26, 224, 'x', 'tr', 'small');
    return g.svg();
  }
  // the tip of E at one point, turning counterclockwise on the page, with the wave going into the page
  function rotFig() {
    const g = PF.fig({ alt: 'the tip of E traces a circle turning counterclockwise on the page, with x to the right and y up; the wave travels into the page' });
    const cx = 120, cy = 110, r = 62;
    g.arrow(cx - 88, cy, cx + 92, cy, { cls: 'dim', hs: 6 });
    g.label(cx + 96, cy, 'x', 'l', 'small');
    g.arrow(cx, cy + 88, cx, cy - 92, { cls: 'dim', hs: 6 });
    g.label(cx, cy - 96, 'y', 'b', 'small');
    g.circle(cx, cy, r, { cls: 'dim' });
    g.arc(cx, cy, r, 12, 70, { cls: 'thick', arrow: 'end', hs: 9 });
    g.arc(cx, cy, r, 192, 250, { cls: 'thick', arrow: 'end', hs: 9 });
    g.arrow(cx, cy, cx + r * Math.cos(Math.PI / 6), cy - r * Math.sin(Math.PI / 6), { cls: 'thick', hs: 8 });
    g.label(cx + 40, cy - 46, '\\mathbf E', 'bl');
    g.otimes(cx + 150, cy + 20, 9);
    g.text(cx + 150, cy + 36, 'travel', 't', 'small');
    return g.svg();
  }
  // |E| in front of an interface: min 0.5 E0 at the boundary, max 1.5 E0, and a flat transmitted field
  function envFig() {
    const G0 = -0.5;
    const env = (z) => Math.hypot(1 + G0 * Math.cos(4 * Math.PI * z), G0 * Math.sin(4 * Math.PI * z));
    return PF.plot({
      w: 380, h: 190, x: [-1, 0.42], y: [0, 1.85], xl: 'z', yl: '|\\tilde E|',
      xt: [[-1, '-\\lambda_1'], [-0.5, '-\\lambda_1/2'], [0, '0']],
      yt: [[0.5, '0.5E_0'], [1.5, '1.5E_0']],
      vlines: [[0, '']],
      curves: [{ f: env, to: 0, n: 400 }, { f: () => 0.5, from: 0, to: 0.42 }],
    });
  }

  const CARDS = [
    // ================================================================ what is it?
    { id: 'c3_def_S', cat: 'def', t: 'The Poynting vector',
      q: md`What does $\mathbf S = \mathbf E\times\mathbf H$ measure, and in what units?`,
      a: md`The power crossing a unit area at that point, in $\text{W/m}^2$. Its direction is the direction the energy moves.`,
      why: md`Units: $(\text{V/m})(\text{A/m}) = \text{W/m}^2$. It is the flux term $\nabla\cdot(\mathbf E\times\mathbf H)$ in the Poynting theorem, just as $\mathbf J$ is the flux in the charge continuity equation $\nabla\cdot\mathbf J + \partial\rho/\partial t = 0$.` },
    { id: 'c3_def_thm', cat: 'def', t: 'The Poynting theorem, term by term',
      q: md`With $w = \tfrac12\epsilon E^2 + \tfrac12\mu H^2$, name the three terms:
        $$\frac{\partial w}{\partial t} + \nabla\cdot\mathbf S + \mathbf J\cdot\mathbf E = 0$$`,
      a: md`The rate of change of stored energy per volume; the net power flowing out per volume; the power handed to the charges per volume (Joule heating).`,
      why: md`It is energy conservation at a point. Dot Faraday's law with $\mathbf H$, dot Ampère's law with $\mathbf E$, and subtract. The identity $\nabla\cdot(\mathbf E\times\mathbf H) = \mathbf H\cdot\nabla\times\mathbf E - \mathbf E\cdot\nabla\times\mathbf H$ turns the two curls into the divergence of $\mathbf S$.` },
    { id: 'c3_def_JE', cat: 'def', t: md`The sign of $\mathbf J\cdot\mathbf E$`,
      q: md`At some point, $\mathbf J\cdot\mathbf E < 0$. What is happening there?`,
      a: md`The current is a **source**: charge is pushed against the field, and energy goes from the charges into the field. $\mathbf J\cdot\mathbf E > 0$ is the opposite: the field does work on the charges (loss, heat).`,
      why: md`It is $vi$ in a circuit: with the passive sign convention, positive $vi$ absorbs and negative $vi$ delivers. A radiating current sheet has $\mathbf J_s\cdot\mathbf E < 0$, because the field it makes points against its own current.` },
    { id: 'c3_def_avg', cat: 'def', t: md`The time average $\langle\mathbf S\rangle$`,
      q: md`For fields at one frequency with phasors $\tilde{\mathbf E}$ and $\tilde{\mathbf H}$, what is the average of $\mathbf E\times\mathbf H$ over one period?`,
      a: md`$$\langle\mathbf S\rangle = \tfrac12\Re\{\tilde{\mathbf E}\times\tilde{\mathbf H}^*\}$$ It is on the formula sheet.`,
      why: md`The instantaneous $\mathbf S$ pulses at $2\omega$. Only the part of $\mathbf H$ in phase with $\mathbf E$ carries power on average. The conjugate picks out that part: $\tilde E\tilde H^*$ has the angle (phase of $E$) minus (phase of $H$), and its real part keeps the in-phase piece.` },
    { id: 'c3_def_phasor', cat: 'def', t: 'A phasor',
      q: md`What is the phasor of $E(t) = E_0\cos(\omega t + \phi)$, and what does it store?`,
      a: md`$\tilde E = E_0e^{j\phi}$, chosen so that $E(t) = \Re\{\tilde Ee^{j\omega t}\}$. It stores the amplitude and the phase. The frequency is understood.`,
      why: md`Euler: $\Re\{E_0e^{j\phi}e^{j\omega t}\} = E_0\cos(\omega t + \phi)$. Every field in the problem shares the same $e^{j\omega t}$, so you drop it, do algebra with complex numbers, and put it back at the end. Cosine is the reference, so a sine has phasor $-j$.` },
    { id: 'c3_def_gamma', cat: 'def', t: md`The propagation constant $\gamma$`,
      q: md`In $\tilde E_x = E_0e^{-\gamma z}$ with $\gamma = \alpha + j\beta$, what do $\alpha$ and $\beta$ do, and in what units?`,
      a: md`$\alpha$ (Np/m) sets the decay: the amplitude falls as $e^{-\alpha z}$. $\beta$ (rad/m) sets the phase: $\lambda = 2\pi/\beta$ and $v_p = \omega/\beta$.`,
      why: md`$e^{-\gamma z} = e^{-\alpha z}e^{-j\beta z}$. The real exponent shrinks the size; the imaginary one only turns the phasor. Back in time: $E_0e^{-\alpha z}\cos(\omega t - \beta z)$.` },
    { id: 'c3_def_eta', cat: 'def', t: md`The intrinsic impedance $\eta$`,
      q: md`What is $\eta = |\eta|e^{j\tau}$ physically, and what does its angle $\tau$ tell you?`,
      a: md`The ratio $\tilde E/\tilde H$ for one traveling wave, in $\Omega$. Its angle $\tau$ (not a transmission coefficient) is how far $H$ lags $E$ in time.`,
      why: md`$\tilde H = \tilde E/\eta$, so $|H| = |E|/|\eta|$ and the phase of $H$ is the phase of $E$ minus $\tau$. Perfect dielectric: $\tau = 0$. Good conductor: $\tau = 45°$. The sheet writes $H_y\propto\cos(\omega t\mp\beta z + \phi - \tau)$.` },
    { id: 'c3_def_losstan', cat: 'def', t: 'The loss tangent',
      q: md`What does the number $\sigma/\omega\epsilon$ compare?`,
      a: md`The size of the conduction current $\sigma E$ to the size of the displacement current $\omega\epsilon E$. Much less than 1: an imperfect (low-loss) dielectric. Much more than 1: a good conductor.`,
      why: md`Ampère in phasors: $\nabla\times\tilde{\mathbf H} = (\sigma + j\omega\epsilon)\tilde{\mathbf E}$. The two currents sit $90°$ apart in one bracket, and their sizes have the ratio $\sigma/\omega\epsilon$. It falls as $1/f$: the same material can be a conductor at low frequency and a dielectric at high frequency.` },
    { id: 'c3_def_skin', cat: 'def', t: 'Skin depth (penetration depth)',
      q: md`What is $\delta$, and how much of the field and of the power is left one $\delta$ into the material?`,
      a: md`$\delta = 1/\alpha$: the distance over which the field falls by a factor $e$. After one $\delta$: field $e^{-1}\approx37\%$, power $e^{-2}\approx13.5\%$.`,
      why: md`The field goes as $e^{-\alpha z}$, so $e^{-\alpha\delta} = e^{-1}$. Power goes as the field squared, $e^{-2\alpha z}$. In a good conductor $\delta = 1/\sqrt{\pi f\mu\sigma}$; it is called "skin" because it is tiny (copper at 1 MHz: $66\ \mu\text{m}$).` },
    { id: 'c3_def_Rs', cat: 'def', t: 'Surface resistance',
      q: md`What is the surface resistance $R_s$ of a good conductor, and what is it for?`,
      a: md`$$R_s = \frac{1}{\sigma\delta} = \sqrt{\frac{\pi f\mu}{\sigma}}$$ The power lost per unit area of surface is $\tfrac12R_s|\tilde J_s|^2$, where $\tilde J_s$ is the total current per unit width.`,
      why: md`The current really flows in a layer a few $\delta$ thick, decaying as $e^{-\gamma z}$. Integrating the heating $\tfrac12|\tilde J|^2/\sigma$ over the depth gives exactly the loss of a uniform layer $\delta$ thick, and a square of such a layer has resistance $1/(\sigma\delta)$.` },
    { id: 'c3_def_vp', cat: 'def', t: 'Phase velocity',
      q: md`What moves at $v_p = \omega/\beta$, and why can $v_p$ depend on frequency in a lossy medium?`,
      a: md`The points of constant phase (crests, zero crossings). In a lossy medium $\beta$ is not proportional to $\omega$, so $v_p$ changes with $f$: the medium is dispersive.`,
      why: md`Hold $\omega t - \beta z$ fixed: $z = (\omega/\beta)t + \text{const}$. In a good conductor $\beta = \sqrt{\pi f\mu\sigma}$, so $v_p\propto\sqrt f$, and it is slow: seawater at 1 kHz has $v_p = 5\times10^4$ m/s.` },
    { id: 'c3_def_pol', cat: 'def', t: 'Polarization',
      q: md`What is the polarization of a wave?`,
      a: md`The shape traced by the tip of $\mathbf E$ at one fixed point during one period: a line (linear), a circle (circular) or an ellipse (elliptical).`,
      why: md`Write $\tilde{\mathbf E} = \hat xA + \hat yB$ at that point. $A$ and $B$ in phase (or $180°$ apart): both parts rise and fall together, a line. Equal sizes and $90°$ apart: a circle. Anything else: an ellipse.` },
    { id: 'c3_def_hand', cat: 'def', t: 'Handedness',
      q: md`When is a circularly (or elliptically) polarized wave right-handed?`,
      a: md`Point your right thumb along the direction of travel. If your fingers curl the way $\mathbf E$ turns in time, it is right-handed. If not, it is left-handed.`,
      why: md`The rotation alone is not enough: the same rotation on a wave going the other way has the other hand. Example: $(\hat x - j\hat y)e^{-j\beta z}$ at $z = 0$ is $\hat x\cos\omega t + \hat y\sin\omega t$, which turns from $x$ to $y$. Thumb along $+z$, the right hand curls from $x$ to $y$: right-handed.` },
    { id: 'c3_def_Gamma', cat: 'def', t: md`$\Gamma$ and $\tau$ for a plane wave`,
      q: md`Define $\Gamma$ and $\tau$ for a wave hitting a flat interface head-on.`,
      a: md`$\Gamma = \tilde E_r/\tilde E_i$ and $\tau = \tilde E_t/\tilde E_i$, all evaluated at the interface. This $\tau$ is the transmission coefficient, $\tau = 1 + \Gamma$ (not the angle of $\eta$).`,
      why: md`Both are ratios of electric-field phasors at the boundary. $1 + \Gamma = \tau$ says tangential $\mathbf E$ is the same on both sides. The magnetic fields have their own ratio: $\tilde H_r/\tilde H_i = -\Gamma$.` },
    { id: 'c3_def_standing', cat: 'def', t: 'A standing wave',
      q: md`What is a standing wave, and how much average power does it carry?`,
      a: md`The sum of two equal waves going opposite ways. Its nodes stay put; every point just oscillates in place. It carries zero average power.`,
      why: md`$e^{-j\beta z} - e^{j\beta z} = -2j\sin\beta z$: position and time separate, $\sin\beta z\,\sin\omega t$. In the phasors, $\tilde E$ and $\tilde H$ are $90°$ apart (a factor $-j$), so $\tfrac12\Re\{\tilde E\tilde H^*\} = 0$. The two waves carry equal power in opposite directions.` },
    { id: 'c3_def_radp', cat: 'def', t: 'Radiation pressure',
      q: md`What is radiation pressure, and how big is it when a wave of average intensity $\langle S_i\rangle$ hits a perfect mirror head-on?`,
      a: md`The force per unit area that a wave exerts on the surface it hits. Perfect mirror: $$P_{rad} = \frac{2\langle S_i\rangle}{c}$$ A perfect absorber feels half that.`,
      why: md`A wave carries momentum: $\langle S\rangle/c$ per unit area per second. A mirror sends it back, so the momentum change is twice that. The mechanism: the induced surface current $\mathbf J$ crosses the field $\mathbf B$, and $\mathbf J\times\mathbf B$ pushes the conductor along the direction of travel.` },
    { id: 'c3_def_GF', cat: 'def', t: 'The geometric factor GF',
      q: md`What is GF for a TEM line, and how do the per-unit-length $\mathcal L$, $\mathcal C$, $\mathcal G$ follow from it?`,
      a: md`A pure number set by the cross-section: $$\mathcal C = \epsilon\,\text{GF},\quad\mathcal G = \sigma\,\text{GF},\quad\mathcal L = \frac{\mu}{\text{GF}}$$ Parallel plates: $\text{GF} = W/d$. Coax: $\text{GF} = 2\pi/\ln(b/a)$.`,
      why: md`All three come from the same field pattern. Capacitance is $\epsilon\oint\mathbf E\cdot d\mathbf S/V$ and conductance is $\sigma\oint\mathbf E\cdot d\mathbf S/V$ over the same surface, so they share the factor; inductance comes out as the inverse. That is why $\mathcal{LC} = \mu\epsilon$ on every TEM line, and $Z_0 = \eta/\text{GF}$.` },
    { id: 'c3_def_Z0', cat: 'def', t: md`Characteristic impedance $Z_0$`,
      q: md`What is $Z_0$ of a line? Could you measure it with an ohmmeter?`,
      a: md`$Z_0 = V^+/I^+$: the voltage-to-current ratio of one wave traveling one way, $Z_0 = \sqrt{\mathcal L/\mathcal C}$. No: an ohmmeter works at DC and sees whatever is at the far end.`,
      why: md`A wave just launched sees only the line ahead of it, with no reflection yet, so $V/I = Z_0$ until the echo comes back. At DC the line is just two wires. $Z_0$ is real yet nothing heats: the energy is stored in the line and carried down it.` },
    { id: 'c3_def_taug', cat: 'def', t: md`The injection coefficient $\tau_g$`,
      q: md`A line is driven by $V_g$ through $R_g$. What is $\tau_g$?`,
      a: md`$$\tau_g = \frac{Z_0}{R_g + Z_0}$$ The fraction of $V_g$ launched onto the line at the start: $V^+ = \tau_gV_g$. (Not the transmission coefficient $1 + \Gamma$, and not the angle of $\eta$.)`,
      why: md`Before any echo returns, the line looks like a resistor $Z_0$ to the source. So the first wave is a voltage divider: $V_g$ shared between $R_g$ and $Z_0$.` },
    { id: 'c3_def_GL', cat: 'def', t: md`$\Gamma_L$ and $\Gamma_g$ on a line`,
      q: md`What do $\Gamma_L$ and $\Gamma_g$ measure?`,
      a: md`$\Gamma_L = \dfrac{R_L - Z_0}{R_L + Z_0}$: reflected over incident voltage wave at the load. $\Gamma_g = \dfrac{R_g - Z_0}{R_g + Z_0}$: the same for a wave arriving back at the generator.`,
      why: md`Same physics at both ends. The end demands $V/I = R$, but a single wave has $V/I = Z_0$; a reflected wave makes up the difference. If $R = Z_0$ there is no mismatch and no reflection.` },
    { id: 'c3_def_bounce', cat: 'def', t: 'A bounce diagram',
      q: md`What are the axes of a bounce diagram, and what is written on each line?`,
      a: md`Position $z$ across (generator at $z = 0$, load at $z = l$), time $t$ downward. Each slanted line is one wave front, labeled with its voltage step (or impulse weight): $\tau_gV_g$, then $\Gamma_L\tau_gV_g$, then $\Gamma_g\Gamma_L\tau_gV_g$, and so on.`,
      why: md`A front moves at speed $v$, so it is a straight line that takes $l/v$ to cross. At each end it turns into a new front multiplied by that end's $\Gamma$. $V(z, t)$ is the sum of every front that has passed $z$ by time $t$.` },
    { id: 'c3_def_Gd', cat: 'def', t: md`The generalized reflection coefficient $\Gamma(d)$`,
      q: md`On a line in sinusoidal steady state, what is $\Gamma(d)$?`,
      a: md`The ratio of the backward wave to the forward wave at distance $d$ from the load: $$\Gamma(d) = \Gamma_Le^{-j2\beta d}$$ Same size as $\Gamma_L$; its angle falls by $2\beta d$.`,
      why: md`In $\tilde V(d) = V^+e^{j\beta d} + V^-e^{-j\beta d}$ divide the second term by the first: $(V^-/V^+)e^{-j2\beta d}$. Stepping back $d$ adds $\beta d$ of phase to the forward wave and removes $\beta d$ from the backward one.` },
    { id: 'c3_def_Zd', cat: 'def', t: md`The line impedance $Z(d)$`,
      q: md`What is $Z(d)$?`,
      a: md`$Z(d) = \tilde V(d)/\tilde I(d)$: the impedance you would measure if you cut the line at $d$ and looked toward the load. $$Z(d) = Z_0\frac{1 + \Gamma(d)}{1 - \Gamma(d)}$$`,
      why: md`$\tilde V = V^+e^{j\beta d}[1 + \Gamma(d)]$ and $\tilde I = \frac{V^+}{Z_0}e^{j\beta d}[1 - \Gamma(d)]$: the minus because the backward wave carries current the other way. $Z(d)$ repeats every $\lambda/2$ and turns into $Z_0^2/Z$ after $\lambda/4$.` },
    { id: 'c3_def_vswr', cat: 'def', t: 'VSWR',
      q: md`What is the VSWR, and what values can it take?`,
      a: md`The largest $|\tilde V|$ on the line divided by the smallest: $$\text{VSWR} = \frac{1 + |\Gamma_L|}{1 - |\Gamma_L|}$$ From 1 (matched, no standing wave) to $\infty$ (a short, an open or a pure reactance, all with $|\Gamma_L| = 1$).`,
      why: md`$|\tilde V(d)| = |V^+|\,|1 + \Gamma(d)|$. As $d$ grows, $\Gamma(d)$ circles with fixed size $|\Gamma_L|$: the sum is biggest when $\Gamma(d)$ points along $+1$ and smallest along $-1$.` },
    { id: 'c3_def_stub', cat: 'def', t: 'Stubs and their resonances',
      q: md`What is a stub, and what do "series resonance" and "parallel resonance" of a shorted stub mean?`,
      a: md`A length of line ending in a short or an open, used as a reactance. Series resonance: input $Z = 0$ (length $n\lambda/2$). Parallel resonance: input $Y = 0$, an open (length an odd multiple of $\lambda/4$).`,
      why: md`A shorted stub has $Z = jZ_0\tan\beta l$. It is zero where $\beta l = n\pi$, like a series LC at resonance, and infinite where $\beta l = \pi/2 + n\pi$, like a parallel LC at resonance.` },
    { id: 'c3_def_qw', cat: 'def', t: 'The quarter-wave transformer',
      q: md`What does a $\lambda/4$ length of line do to the load at its far end?`,
      a: md`It inverts the load's impedance about $Z_0$: $$Z_{in} = \frac{Z_0^2}{Z_L}$$ A short looks like an open, a big resistor like a small one, an inductor like a capacitor.`,
      why: md`A quarter wave turns each traveling wave by $90°$ ($e^{\pm j\pi/2} = \pm j$). That swaps the roles of voltage and current: the input voltage is $jZ_0$ times the load current, and the input current is $j/Z_0$ times the load voltage.` },

    // ================================================================ derive it in three lines
    { id: 'c3_der_jw', cat: 'derive', t: md`Why $\partial/\partial t$ becomes $j\omega$`,
      q: md`Show that the phasor of $\partial E/\partial t$ is $j\omega\tilde E$.`,
      a: md`Differentiate $E = \Re\{\tilde Ee^{j\omega t}\}$: $$\frac{\partial E}{\partial t} = \Re\{j\omega\tilde Ee^{j\omega t}\}$$ So the phasor of the derivative is $j\omega\tilde E$.`,
      why: md`Only $e^{j\omega t}$ depends on time, and its derivative is $j\omega e^{j\omega t}$. Taking the real part and differentiating can be swapped (both are linear). This one step turns Maxwell's equations into algebra.` },
    { id: 'c3_der_avg', cat: 'derive', t: md`Why $\langle S\rangle = \tfrac12\Re\{\tilde E\tilde H^*\}$`,
      q: md`Derive the time average of $E(t)H(t)$ from the phasors.`,
      a: md`Write $E = \tfrac12(\tilde Ee^{j\omega t} + \tilde E^*e^{-j\omega t})$ and the same for $H$. Multiply:
        $$\begin{aligned}EH &= \tfrac14(\tilde E\tilde H^* + \text{c.c.})\\ &\quad + \tfrac14(\tilde E\tilde He^{j2\omega t} + \text{c.c.})\end{aligned}$$
        The $2\omega$ term averages to zero, leaving $\tfrac12\Re\{\tilde E\tilde H^*\}$.`,
      why: md`$\Re\{z\} = (z + z^*)/2$, so a number plus its conjugate (c.c.) is twice its real part. A cosine at $2\omega$ has zero average. It is the same proof as $\langle p\rangle = \tfrac12\Re\{VI^*\}$ in circuits.` },
    { id: 'c3_der_wave', cat: 'derive', t: md`$\gamma^2 = j\omega\mu(\sigma + j\omega\epsilon)$`,
      q: md`Start from the phasor curl equations for $\tilde E_x(z)$ and $\tilde H_y(z)$ in a medium with $\sigma$, $\epsilon$, $\mu$. Derive the wave equation and $\gamma$.`,
      a: md`Faraday: $d\tilde E_x/dz = -j\omega\mu\tilde H_y$. Ampère: $d\tilde H_y/dz = -(\sigma + j\omega\epsilon)\tilde E_x$. Differentiate the first and substitute the second:
        $$\frac{d^2\tilde E_x}{dz^2} = \gamma^2\tilde E_x$$
        with $\gamma^2 = j\omega\mu(\sigma + j\omega\epsilon)$.`,
      why: md`The two minus signs cancel. $e^{\mp\gamma z}$ solves it, since each derivative pulls down a factor $\mp\gamma$. Take the root with $\Re\{\gamma\} > 0$, so that $e^{-\gamma z}$ decays in the direction it travels.` },
    { id: 'c3_der_etagamma', cat: 'derive', t: md`$\eta\gamma = j\omega\mu$ and $\gamma/\eta = \sigma + j\omega\epsilon$`,
      q: md`Put $\tilde E_x = E_0e^{-\gamma z}$ and $\tilde H_y = (E_0/\eta)e^{-\gamma z}$ into the two curl equations. What comes out?`,
      a: md`Faraday: $-\gamma E_0 = -j\omega\mu E_0/\eta$, so $\eta\gamma = j\omega\mu$. Ampère: $-\gamma E_0/\eta = -(\sigma + j\omega\epsilon)E_0$, so $\gamma/\eta = \sigma + j\omega\epsilon$.`,
      why: md`Multiply the two: $\gamma^2 = j\omega\mu(\sigma + j\omega\epsilon)$. Divide: $\eta^2 = j\omega\mu/(\sigma + j\omega\epsilon)$. Read backward they give the material from a measured wave: $\sigma = \Re\{\gamma/\eta\}$, $\epsilon = \Im\{\gamma/\eta\}/\omega$, $\mu = \gamma\eta/j\omega$ (all on the sheet).` },
    { id: 'c3_der_tau', cat: 'derive', t: md`The angle of $\eta$`,
      q: md`Derive $\tau = \tfrac12\tan^{-1}(\sigma/\omega\epsilon)$, the angle of $\eta$.`,
      a: md`Divide top and bottom of $\eta^2$ by $j\omega\epsilon$, using $1/j = -j$:
        $$\eta = \frac{\sqrt{\mu/\epsilon}}{\sqrt{1 - j\sigma/\omega\epsilon}}$$
        The bracket has angle $-\tan^{-1}(\sigma/\omega\epsilon)$. The square root halves it; dividing flips its sign: $\tau = +\tfrac12\tan^{-1}(\sigma/\omega\epsilon)$.`,
      why: md`$\eta^2 = \frac{j\omega\mu}{\sigma + j\omega\epsilon} = \frac{\mu/\epsilon}{1 + \sigma/(j\omega\epsilon)}$. Since $\tan^{-1}$ never exceeds $90°$, $\tau$ runs from $0$ (no loss) up to $45°$ (good conductor) and never beyond.` },
    { id: 'c3_der_lowloss', cat: 'derive', t: md`Imperfect dielectric: $\alpha$ in one line`,
      q: md`For $\sigma/\omega\epsilon\ll1$, derive $\alpha\approx\tfrac{\sigma}{2}\sqrt{\mu/\epsilon}$ and $\beta\approx\omega\sqrt{\mu\epsilon}$.`,
      a: md`Factor $\gamma$ as
        $$\gamma = j\omega\sqrt{\mu\epsilon}\Big(1 - j\frac{\sigma}{\omega\epsilon}\Big)^{1/2}$$
        and use $(1 + x)^{1/2}\approx1 + x/2$:
        $$\gamma\approx\frac{\sigma}{2}\sqrt{\frac{\mu}{\epsilon}} + j\omega\sqrt{\mu\epsilon}$$`,
      why: md`$j\cdot(-j) = 1$ turns the small imaginary correction into a real part: the decay. Note that $\alpha\approx\tfrac12\sigma|\eta|$ has no frequency in it.` },
    { id: 'c3_der_good', cat: 'derive', t: md`Good conductor: $\alpha = \beta$`,
      q: md`For $\sigma/\omega\epsilon\gg1$, derive $\alpha = \beta = \sqrt{\pi f\mu\sigma}$.`,
      a: md`Drop $j\omega\epsilon$ next to $\sigma$: $\gamma\approx\sqrt{j\omega\mu\sigma}$. Since $\sqrt j = e^{j45°} = (1 + j)/\sqrt2$,
        $$\gamma\approx(1 + j)\sqrt{\frac{\omega\mu\sigma}{2}}$$
        and $\omega/2 = \pi f$.`,
      why: md`Equal real and imaginary parts: the wave decays by $e^{-2\pi}\approx0.2\%$ in a single wavelength, since $\lambda = 2\pi/\beta = 2\pi\delta$.` },
    { id: 'c3_der_etagood', cat: 'derive', t: md`Good conductor: $\eta = (1 + j)R_s$`,
      q: md`Derive $\eta$ in a good conductor and connect it to the surface resistance.`,
      a: md`$$\eta\approx\sqrt{\frac{j\omega\mu}{\sigma}} = (1 + j)\sqrt{\frac{\pi f\mu}{\sigma}}$$ That is $(1 + j)R_s$: $|\eta| = \sqrt{\omega\mu/\sigma}$ and $\tau = 45°$.`,
      why: md`The same $\sqrt j = (1 + j)/\sqrt2$ step as for $\gamma$. $|\eta|$ is tiny (copper at 1 GHz: about $0.012\ \Omega$), which is why metals reflect almost everything: $\Gamma\approx-1$.` },
    { id: 'c3_der_Gamma', cat: 'derive', t: md`$\Gamma = (\eta_2 - \eta_1)/(\eta_2 + \eta_1)$`,
      q: md`Derive $\Gamma$ and $\tau$ at normal incidence from the boundary conditions.`,
      a: md`Tangential $\mathbf E$ continuous: $1 + \Gamma = \tau$. Tangential $\mathbf H$ continuous, with the reflected $H$ flipped: $(1 - \Gamma)/\eta_1 = \tau/\eta_2$. Put $\tau = 1 + \Gamma$ into the second:
        $$\Gamma = \frac{\eta_2 - \eta_1}{\eta_2 + \eta_1}$$`,
      why: md`All fields are divided by $E_0$ at $z = 0$. The reflected wave travels the other way, so its $\mathbf H$ points the other way ($\hat e\times\hat h$ must be $-\hat z$). No surface current, unless region 2 is a perfect conductor.` },
    { id: 'c3_der_power', cat: 'derive', t: md`Power splits as $\Gamma^2$ and $1 - \Gamma^2$`,
      q: md`Lossless media, real $\eta_1$ and $\eta_2$. Show that reflected plus transmitted power equals the incident power.`,
      a: md`Each wave carries $|E|^2/2\eta$ per area. Reflected: $\Gamma^2\langle S_i\rangle$. Transmitted: $\tau^2(\eta_1/\eta_2)\langle S_i\rangle$, and with $\tau = 2\eta_2/(\eta_1 + \eta_2)$,
        $$\tau^2\frac{\eta_1}{\eta_2} = \frac{4\eta_1\eta_2}{(\eta_1 + \eta_2)^2} = 1 - \Gamma^2$$`,
      why: md`$1 - \Gamma^2 = \frac{(\eta_1 + \eta_2)^2 - (\eta_2 - \eta_1)^2}{(\eta_1 + \eta_2)^2}$, and the top is $4\eta_1\eta_2$. So $\tau$ can exceed 1 (when $\eta_2 > \eta_1$) without creating energy: a bigger field in a higher-impedance medium carries less power.` },
    { id: 'c3_der_pec', cat: 'derive', t: 'Standing wave in front of a mirror',
      q: md`A wave $\hat xE_0e^{-j\beta z}$ hits a perfect conductor at $z = 0$. Derive the total $\tilde E$ and $\tilde H$ for $z < 0$.`,
      a: md`$\Gamma = -1$, so
        $$\tilde E_x = E_0(e^{-j\beta z} - e^{j\beta z}) = -2jE_0\sin\beta z$$
        $$\tilde H_y = \frac{E_0}{\eta}(e^{-j\beta z} + e^{j\beta z}) = \frac{2E_0}{\eta}\cos\beta z$$`,
      why: md`$e^{jx} - e^{-jx} = 2j\sin x$ and $e^{jx} + e^{-jx} = 2\cos x$. $E$ is zero at the wall and $H$ is largest there, $2E_0/\eta$. The reflected $H$ adds because $\Gamma = -1$ times the sign flip of a backward wave is $+1$.` },
    { id: 'c3_der_Js', cat: 'derive', t: 'The current on the mirror',
      q: md`For that mirror, find the surface current $\tilde{\mathbf J}_s$.`,
      a: md`$\mathbf J_s = \hat n\times\mathbf H$, with $\hat n = -\hat z$ pointing out of the conductor into the fields:
        $$\tilde{\mathbf J}_s = -\hat z\times\hat y\frac{2E_0}{\eta} = \hat x\frac{2E_0}{\eta}$$`,
      why: md`Inside a perfect conductor $\mathbf H = 0$, so the whole tangential $H$ at the surface is the jump. $-\hat z\times\hat y = \hat x$. This current, radiating both ways, cancels the wave inside and makes the reflected wave. In a real metal the same total current flows within a few $\delta$.` },
    { id: 'c3_der_tel', cat: 'derive', t: "A telegrapher's equation from Faraday's law",
      q: md`Parallel plates, gap $d$, width $W$, fields $E_x(z, t)$ and $H_y(z, t)$. Derive $-\partial V/\partial z = \mathcal L\,\partial I/\partial t$.`,
      a: md`Faraday: $\partial E_x/\partial z = -\mu\,\partial H_y/\partial t$. Multiply by $d$ and use $V = E_xd$, $I = H_yW$:
        $$-\frac{\partial V}{\partial z} = \frac{\mu d}{W}\frac{\partial I}{\partial t}$$
        so $\mathcal L = \mu d/W$.`,
      why: md`$V$ is $\int\mathbf E\cdot d\mathbf l$ across the gap; $I$ is the surface current $J_s = H_y$ on a plate times its width. Ampère the same way gives $-\partial I/\partial z = \mathcal C\,\partial V/\partial t$ with $\mathcal C = \epsilon W/d$.` },
    { id: 'c3_der_Z0', cat: 'derive', t: md`$Z_0 = \sqrt{\mathcal L/\mathcal C}$`,
      q: md`Put $V = f(t - z/v)$ into $-\partial I/\partial z = \mathcal C\,\partial V/\partial t$. Find $I$ and $Z_0$.`,
      a: md`The right side is $\mathcal Cf'$. A function of $t - z/v$ with that $z$-derivative is $I = \mathcal Cvf$, so
        $$Z_0 = \frac VI = \frac{1}{\mathcal Cv} = \sqrt{\frac{\mathcal L}{\mathcal C}}$$`,
      why: md`$\partial/\partial z$ of $f(t - z/v)$ is $-f'/v$, so $I = \mathcal Cvf$ gives $-\partial I/\partial z = \mathcal Cf'$. Then use $v = 1/\sqrt{\mathcal{LC}}$. A backward wave $g(t + z/v)$ gives $I = -g/Z_0$: the current flips sign, not size.` },
    { id: 'c3_der_GL', cat: 'derive', t: md`$\Gamma_L$ from Ohm's law at the load`,
      q: md`Derive $\Gamma_L = V^-/V^+$ at a resistor $R_L$.`,
      a: md`At the load $V = V^+ + V^-$ and $I = (V^+ - V^-)/Z_0$. Ohm's law $V = R_LI$:
        $$V^+ + V^- = \frac{R_L}{Z_0}(V^+ - V^-)$$
        Solve for the ratio: $\Gamma_L = \dfrac{R_L - Z_0}{R_L + Z_0}$.`,
      why: md`The backward wave's current is $-V^-/Z_0$. Checks: an open ($R_L\to\infty$) gives $+1$ (the current must vanish), a short gives $-1$ (the voltage must vanish), a match gives 0.` },
    { id: 'c3_der_ss', cat: 'derive', t: 'The steady state of a bounce problem',
      q: md`Step $V_g$ through $R_g$, line $Z_0$, load $R_L$. What does the load voltage settle to, and why?`,
      a: md`$$V_\infty = V_g\frac{R_L}{R_g + R_L}$$ The sum of all the bounces, $\tau_gV_g\frac{1 + \Gamma_L}{1 - \Gamma_L\Gamma_g}$, simplifies to exactly this.`,
      why: md`Once the echoes die, nothing changes in time: $\mathcal L\,\partial I/\partial t = 0$ and $\mathcal C\,\partial V/\partial t = 0$, so the line is two plain wires and the circuit is a voltage divider. $Z_0$ drops out. Use it to check any bounce diagram.` },
    { id: 'c3_der_short', cat: 'derive', t: md`Shorted stub: $Z = jZ_0\tan\beta d$`,
      q: md`A line ends in a short at $d = 0$. Derive $Z(d)$.`,
      a: md`$\tilde V(0) = 0$ forces $V^- = -V^+$. Then
        $$\tilde V(d) = 2jV^+\sin\beta d$$
        $$\tilde I(d) = \frac{2V^+}{Z_0}\cos\beta d$$
        Divide: $Z(d) = jZ_0\tan\beta d$.`,
      why: md`$e^{j\beta d} - e^{-j\beta d} = 2j\sin\beta d$; the current has $+$ between its two terms, giving $2\cos\beta d$. Purely imaginary: a shorted line stores energy and never absorbs it.` },
    { id: 'c3_der_open', cat: 'derive', t: md`Open stub: $Z = -jZ_0\cot\beta d$`,
      q: md`A line ends in an open at $d = 0$. Derive $Z(d)$.`,
      a: md`$\tilde I(0) = 0$ forces $V^- = V^+$. Then $\tilde V = 2V^+\cos\beta d$ and $\tilde I = (2jV^+/Z_0)\sin\beta d$. Divide:
        $$Z(d) = \frac{Z_0}{j\tan\beta d} = -jZ_0\cot\beta d$$`,
      why: md`The sheet writes it as $Y(d) = jY_0\tan\beta d$. A short open stub ($d < \lambda/4$) is a capacitor, and an open looks like a short a quarter wave back.` },
    { id: 'c3_der_qw', cat: 'derive', t: md`$Z(\lambda/4) = Z_0^2/Z_L$`,
      q: md`Derive the input impedance of a quarter-wave line.`,
      a: md`At $d = \lambda/4$, $e^{\pm j\beta d} = \pm j$:
        $$\tilde V_{in} = j(V^+ - V^-) = jZ_0\tilde I_L$$
        $$\tilde I_{in} = \frac{j(V^+ + V^-)}{Z_0} = \frac{j\tilde V_L}{Z_0}$$
        Divide: $Z_{in} = Z_0^2/Z_L$.`,
      why: md`At the load, $V^+ + V^- = \tilde V_L$ and $V^+ - V^- = Z_0\tilde I_L$. The quarter wave swaps voltage and current (times $Z_0$), so the impedance turns upside down. Solving the first line for $\tilde I_L$ gives current forcing, $\tilde I_L = -j\tilde V_{in}/Z_0$.` },
    { id: 'c3_der_hw', cat: 'derive', t: md`$Z(\lambda/2) = Z_L$`,
      q: md`Derive what a half-wave line does to voltage, current and impedance.`,
      a: md`At $d = \lambda/2$, $e^{\pm j\pi} = -1$: $\tilde V_{in} = -(V^+ + V^-) = -\tilde V_L$ and $\tilde I_{in} = -\tilde I_L$. So $Z_{in} = Z_L$.`,
      why: md`Both waves turn by $180°$, so the voltage and the current both flip and their ratio is unchanged. That is why $Z(d)$ repeats every $\lambda/2$. It holds only at the frequency where the line is $\lambda/2$ long.` },
    { id: 'c3_der_junction', cat: 'derive', t: 'Two lines joined',
      q: md`A wave $V^+$ on line $Z_1$ meets line $Z_2$ (no wave coming back on line 2 yet). Derive $\Gamma_{12}$ and $\tau_{12}$.`,
      a: md`Voltage continuous: $V^+ + V^- = V^{++}$. Current continuous: $(V^+ - V^-)/Z_1 = V^{++}/Z_2$. Solve:
        $$\Gamma_{12} = \frac{Z_2 - Z_1}{Z_2 + Z_1}$$
        and $\tau_{12} = 1 + \Gamma_{12}$.`,
      why: md`To the arriving wave, line 2 looks like a resistor $Z_2$ until its own echo returns, so this is the load formula with $R_L = Z_2$. With a shunt resistor $R$ at the junction, use $R\parallel Z_2$ in place of $Z_2$.` },
    { id: 'c3_der_reson', cat: 'derive', t: 'Resonances of an open-ended line',
      q: md`A line of length $l$ is open at both ends, with no source. At which frequencies can it ring?`,
      a: md`$$f_n = n\frac{v}{2l},\quad n = 1, 2, 3, \ldots$$ that is, whenever $l = n\lambda/2$.`,
      why: md`$I = [f(t - z/v) - g(t + z/v)]/Z_0$. $I(0, t) = 0$ forces $g = f$. $I(l, t) = 0$ forces $f(t - l/v) = f(t + l/v)$: $f$ repeats every round trip $2l/v$, so its Fourier series has the frequencies $nv/2l$.` },

    // ================================================================ formulas to carry
    { id: 'c3_rec_delta', cat: 'recall', t: 'Skin depth formula',
      q: md`Good conductor: $\delta$ in terms of $f$, $\mu$, $\sigma$? Is it on the formula sheet?`,
      a: md`$$\delta = \frac1\alpha = \frac{1}{\sqrt{\pi f\mu\sigma}}$$ **Not on the sheet** (only $\alpha\approx\sqrt{\omega\mu\sigma/2}$ is). Carry it.`,
      why: md`$\alpha = \sqrt{\omega\mu\sigma/2} = \sqrt{2\pi f\mu\sigma/2} = \sqrt{\pi f\mu\sigma}$, and $\delta$ is its inverse.`,
      ex: { expr: '1/sqrt(pi*f*mu*sigma)', vars: { f: [1e3, 1e9], mu: [1e-6, 1e-5], sigma: [1, 1e7] } }, exWhat: 'δ using f, mu, sigma' },
    { id: 'c3_rec_Rs', cat: 'recall', t: 'Surface resistance formula',
      q: md`$R_s$ of a good conductor in terms of $f$, $\mu$, $\sigma$? On the sheet?`,
      a: md`$$R_s = \frac{1}{\sigma\delta} = \sqrt{\frac{\pi f\mu}{\sigma}}$$ **Not on the sheet.** Loss per unit area: $\tfrac12R_s|\tilde J_s|^2$.`,
      why: md`$1/(\sigma\delta) = \sqrt{\pi f\mu\sigma}/\sigma$, and $\sqrt\sigma/\sigma = 1/\sqrt\sigma$. It is also $\Re\{\eta\}$ of the conductor, since $\eta = (1 + j)R_s$.`,
      ex: { expr: 'sqrt(pi*f*mu/sigma)', vars: { f: [1e3, 1e9], mu: [1e-6, 1e-5], sigma: [1, 1e7] } }, exWhat: 'Rs using f, mu, sigma' },
    { id: 'c3_rec_Sdecay', cat: 'recall', t: 'Power in a lossy medium',
      q: md`A wave $\hat xE_0e^{-\gamma z}$ in a medium with $\eta = |\eta|e^{j\tau}$. Average power per unit area at depth $z$?`,
      a: md`$$\langle S_z\rangle = \frac{|E_0|^2}{2|\eta|}\cos\tau\,e^{-2\alpha z}$$ **Not on the sheet** in this form; the sheet gives $\tfrac12\Re\{\tilde{\mathbf E}\times\tilde{\mathbf H}^*\}$.`,
      why: md`$\tilde H = \tilde E/\eta$, so $\tilde E\tilde H^* = |\tilde E|^2/\eta^*$, and $1/\eta^* = e^{j\tau}/|\eta|$. The real part brings $\cos\tau$. Two factors of $e^{-\alpha z}$: power decays twice as fast as the field.` },
    { id: 'c3_rec_dB', cat: 'recall', t: 'Attenuation in decibels',
      q: md`The loss in dB after a distance $z$, in terms of $\alpha$?`,
      a: md`$$\text{loss (dB)} = 8.686\,\alpha z$$ **Not on the sheet.** One skin depth costs $8.7$ dB.`,
      why: md`The power ratio is $e^{2\alpha z}$: $10\log_{10}e^{2\alpha z} = 20\alpha z\log_{10}e = 8.686\,\alpha z$. The field ratio with $20\log$ gives the same number.` },
    { id: 'c3_rec_pwr', cat: 'recall', t: 'Reflected and transmitted power',
      q: md`Lossless media. Which fractions of the incident power are reflected and transmitted?`,
      a: md`Reflected $|\Gamma|^2$. Transmitted $1 - |\Gamma|^2 = |\tau|^2\eta_1/\eta_2$. **Not on the sheet** (only $\Gamma$ and $\tau = 1 + \Gamma$ are).`,
      why: md`Power per unit area is $|E|^2/2\eta$. The transmitted wave has field $\tau E_0$ but lives in $\eta_2$. Never use $|\tau|^2$ alone: with $\eta_2 > \eta_1$, $\tau > 1$.` },
    { id: 'c3_rec_radp', cat: 'recall', t: 'Radiation pressure formula',
      q: md`Average pressure on a perfect mirror (normal incidence)? On a perfect absorber?`,
      a: md`Mirror: $2\langle S_i\rangle/c$. Absorber: $\langle S_i\rangle/c$. **Not on the sheet.**`,
      why: md`The momentum flow of a wave is $\langle S\rangle/c$ per unit area. An absorber takes all of it. A mirror takes it and sends it back reversed: twice as much. Units: $(\text{W/m}^2)/(\text{m/s}) = \text{N/m}^2$.`,
      ex: { expr: '2*S/c', vars: { S: [1, 1000], c: [1e8, 3e8] } }, exWhat: 'the mirror pressure using S and c' },
    { id: 'c3_rec_pec', cat: 'recall', t: 'Fields in front of a perfect conductor',
      q: md`Incident $\hat xE_0e^{-j\beta z}$, perfect conductor at $z = 0$. Total $\tilde E$ and $\tilde H$, and where are their nodes?`,
      a: md`$\tilde E = -\hat x\,2jE_0\sin\beta z$ and $\tilde H = \hat y\,(2E_0/\eta)\cos\beta z$. $E$ nodes at $z = -n\lambda/2$ (the wall is one); $H$ nodes halfway between, a quarter wave from them. **Not on the sheet.**`,
      why: md`The wall forces $E = 0$ on it. Zeros of $\sin$ and $\cos$ alternate every $\lambda/4$. In time, $E\propto\sin\beta z\sin\omega t$ and $H\propto\cos\beta z\cos\omega t$: $90°$ apart in both space and time.` },
    { id: 'c3_rec_env', cat: 'recall', t: 'Envelope of a partial standing wave',
      q: md`Incident amplitude $E_0$, reflection coefficient $\Gamma$. Largest and smallest $|\tilde E|$ in region 1?`,
      a: md`$$|E|_{max} = |E_0|(1 + |\Gamma|)$$ $$|E|_{min} = |E_0|(1 - |\Gamma|)$$ **Not on the sheet** for waves (the line version, VSWR, is).`,
      why: md`$|\tilde E| = |E_0|\,|1 + \Gamma e^{j2\beta z}|$. The second term spins as $z$ changes, and the sum is largest when both point the same way. Maxima and minima are $\lambda/4$ apart. $\Gamma > 0$: a maximum at the boundary. $\Gamma < 0$: a minimum there.` },
    { id: 'c3_rec_coax', cat: 'recall', t: 'Coax: L, C and Z₀',
      q: md`Coax with inner radius $a$, outer radius $b$, filled with $\epsilon$, $\mu$. Give $\mathcal C$, $\mathcal L$ and $Z_0$.`,
      a: md`$$\mathcal C = \frac{2\pi\epsilon}{\ln(b/a)},\quad\mathcal L = \frac{\mu}{2\pi}\ln\frac ba$$ $$Z_0 = \frac{\eta}{2\pi}\ln\frac ba$$ With $\mu = \mu_0$: $Z_0 = (60/\sqrt{\epsilon_r})\ln(b/a)\ \Omega$. **Not on the sheet** (it gives $Z_0 = \eta/\text{GF}$, but not GF).`,
      why: md`$\text{GF} = 2\pi/\ln(b/a)$. From Exam 2: the field between the conductors goes as $1/r$, so $V = \frac{\rho_l}{2\pi\epsilon}\ln(b/a)$ and $\mathcal C = \rho_l/V$. Then $\mathcal L = \mu\epsilon/\mathcal C$.`,
      ex: { expr: '(eta/(2*pi))*ln(b/a)', vars: { eta: [50, 400], a: [0.5, 1.5], b: [2, 8] } }, exWhat: 'Z0 using eta, a, b' },
    { id: 'c3_rec_pp', cat: 'recall', t: 'Parallel plates: L, C and Z₀',
      q: md`Plates of width $W$, gap $d$ ($W\gg d$), filled with $\epsilon$, $\mu$. Give $\mathcal C$, $\mathcal L$ and $Z_0$.`,
      a: md`$$\mathcal C = \frac{\epsilon W}{d},\quad\mathcal L = \frac{\mu d}{W},\quad Z_0 = \eta\frac dW$$ **Not on the sheet.**`,
      why: md`$\text{GF} = W/d$: a parallel-plate capacitor per unit length. $Z_0 = \sqrt{\mathcal L/\mathcal C}$. Wider plates mean more capacitance, less inductance, lower $Z_0$.`,
      ex: { expr: 'eta*d/W', vars: { eta: [50, 400], d: [1e-4, 1e-2], W: [1e-3, 1e-1] } }, exWhat: 'Z0 using eta, d, W' },
    { id: 'c3_rec_G', cat: 'recall', t: 'Leakage conductance',
      q: md`The filling between the conductors has conductivity $\sigma$. Conductance per unit length $\mathcal G$?`,
      a: md`$\mathcal G = \sigma\,\text{GF}$, so $\mathcal G/\mathcal C = \sigma/\epsilon$. **Not on the sheet.**`,
      why: md`The conduction current $\sigma E$ and the displacement current $\epsilon\,\partial E/\partial t$ flow through the same field pattern, so the geometry factor is shared. Same reason $RC = \epsilon/\sigma$ for any capacitor with a lossy filling (Exam 2).` },
    { id: 'c3_rec_LC', cat: 'recall', t: md`$\mathcal{LC} = \mu\epsilon$`,
      q: md`For any TEM line, what is $\mathcal{LC}$, and what does it give you?`,
      a: md`$\mathcal{LC} = \mu\epsilon$, so $v = 1/\sqrt{\mathcal{LC}} = 1/\sqrt{\mu\epsilon}$. **On the sheet** (the $v_p$ entry on page 3). Also: $\mathcal L = Z_0/v$ and $\mathcal C = 1/(Z_0v)$.`,
      why: md`$\mathcal L = \mu/\text{GF}$ and $\mathcal C = \epsilon\,\text{GF}$: GF cancels in the product. A line carries a plane wave guided by the conductors, so it moves at the speed of light in the filling. $Z_0/v = \sqrt{\mathcal L/\mathcal C}\sqrt{\mathcal{LC}} = \mathcal L$.` },
    { id: 'c3_rec_ssI', cat: 'recall', t: 'Steady-state current',
      q: md`Step $V_g$ through $R_g$, lossless line, load $R_L$. Final current?`,
      a: md`$$I_\infty = \frac{V_g}{R_g + R_L}$$ **Not on the sheet.**`,
      why: md`At DC the line is two wires. The sum of the current bounces, $\frac{\tau_gV_g}{Z_0}\cdot\frac{1 - \Gamma_L}{1 - \Gamma_L\Gamma_g}$, simplifies to the same thing.`,
      ex: { expr: 'Vg/(Rg+RL)', vars: { Vg: [1, 20], Rg: [10, 200], RL: [10, 200] } }, exWhat: 'I using Vg, Rg, RL' },
    { id: 'c3_rec_junc', cat: 'recall', t: 'Junction coefficients',
      q: md`A wave on line 1 ($Z_1$) meets line 2 ($Z_2$). Give $\Gamma_{12}$ and $\tau_{12}$. What changes with a shunt resistor $R$ at the junction?`,
      a: md`$\Gamma_{12} = \dfrac{Z_2 - Z_1}{Z_2 + Z_1}$ and $\tau_{12} = 1 + \Gamma_{12}$. With a shunt $R$: use $R\parallel Z_2$ in place of $Z_2$; still $\tau_{12} = 1 + \Gamma_{12}$. **Not on the sheet.**`,
      why: md`The arriving wave sees $Z_2$ (or $R\parallel Z_2$) as its load. A shunt element keeps the voltage continuous, so $\tau = 1 + \Gamma$. A series $R$ does not: then $\Gamma_{12}$ uses $R + Z_2$, and $\tau_{12} = (1 + \Gamma_{12})\frac{Z_2}{R + Z_2}$.`,
      ex: { expr: '(Z2-Z1)/(Z2+Z1)', vars: { Z1: [10, 200], Z2: [10, 200] } }, exWhat: 'Γ12 using Z1, Z2' },
    { id: 'c3_rec_qw', cat: 'recall', t: 'The three quarter-wave results',
      q: md`Which three quarter-wave results must you carry?`,
      a: md`$Z_{in} = Z_0^2/Z_L$. A matching section between real $R$ and $Z_L$ has $Z_0 = \sqrt{RZ_L}$. Current forcing: $\tilde I_L = -j\tilde V_{in}/Z_0$. **None of them is on the sheet.**`,
      why: md`All three come from $e^{\pm j\pi/2} = \pm j$ in $\tilde V(d)$ and $\tilde I(d)$. Current forcing is $\tilde V_{in} = jZ_0\tilde I_L$ solved for $\tilde I_L$, with $1/j = -j$: the load current does not depend on the load.`,
      ex: { expr: 'Z0^2/ZL', vars: { Z0: [20, 200], ZL: [10, 300] } }, exWhat: 'Zin using Z0, ZL' },
    { id: 'c3_rec_hw', cat: 'recall', t: 'The half-wave results',
      q: md`A $\lambda/2$ line: input impedance, and input voltage in terms of the load voltage?`,
      a: md`$Z_{in} = Z_L$, $\tilde V_{in} = -\tilde V_L$, $\tilde I_{in} = -\tilde I_L$. **Not on the sheet** (though $z(d) = z(d\pm\lambda/2)$ is).`,
      why: md`$e^{\pm j\pi} = -1$ flips both traveling waves. Watch the sign: the impedance repeats, the voltage does not.` },
    { id: 'c3_rec_res', cat: 'recall', t: 'Resonant frequencies of a line',
      q: md`A line of length $l$, speed $v$. Resonances when both ends are open (or both shorted)? When one end is open and the other shorted?`,
      a: md`Same ends: $f = n\,v/2l$, so $l = n\lambda/2$. Mixed ends: $f = (2n + 1)\,v/4l$, so $l$ is an odd number of quarter waves. **Not on the sheet.**`,
      why: md`$V$ is zero at a short and peaks at an open (the current, the other way round). Zero to zero, or peak to peak, takes a whole number of half waves. Zero to peak takes an odd number of quarter waves.` },
    { id: 'c3_rec_stubsmall', cat: 'recall', t: 'Short stubs as L and C',
      q: md`A shorted stub and an open stub, each much shorter than $\lambda/4$. Which lumped elements are they?`,
      a: md`Shorted: an inductor, $Z\approx j\omega(\mathcal Ll)$. Open: a capacitor, $Y\approx j\omega(\mathcal Cl)$. **Not on the sheet.**`,
      why: md`$\tan x\approx x$ for small $x$: $jZ_0\tan\beta l\approx jZ_0\beta l = j\sqrt{\mathcal L/\mathcal C}\,\omega\sqrt{\mathcal{LC}}\,l = j\omega\mathcal Ll$. A short loop of wire is an inductor; two short open wires are a capacitor.` },
    { id: 'c3_rec_sheetwave', cat: 'recall', t: 'Fields of a current sheet',
      q: md`A surface current $\mathbf J_s = \hat xJ_s(t)$ on $z = 0$ in a medium $\eta$. The fields on both sides?`,
      a: md`$$\mathbf E = -\hat x\frac\eta2J_s(t\mp z/v)$$ $$\mathbf H = \mp\hat y\,\tfrac12J_s(t\mp z/v)$$ Upper signs for $z > 0$. **On the sheet**, but written for $\mathbf J_s = -\hat xJ_s(t)$: mind the sign.`,
      why: md`Half the sheet's current feeds each side, and each wave has $E = \eta H$. $\mathbf E$ points against $\mathbf J_s$, so $\mathbf J_s\cdot\mathbf E < 0$: the sheet is a source. The jump in $H_y$ across the sheet is $J_s$ (the boundary condition).` },
    { id: 'c3_rec_circS', cat: 'recall', t: 'Power of a circular wave',
      q: md`$\tilde{\mathbf E} = E_0(\hat x - j\hat y)e^{-j\beta z}$ in a lossless medium. $\langle S_z\rangle$?`,
      a: md`$$\langle S_z\rangle = \frac{|E_0|^2}{\eta}$$ Twice a linear wave of the same amplitude. **Not on the sheet**; it follows from $\tfrac12\Re\{\tilde{\mathbf E}\times\tilde{\mathbf H}^*\}$.`,
      why: md`The $x$ and $y$ parts are two linear waves, each carrying $|E_0|^2/2\eta$, and their powers add. Another way to see it: $|\mathbf E|$ never passes through zero, it just turns.` },
    { id: 'c3_rec_p2', cat: 'recall', t: 'What page 2 of the sheet gives you',
      q: md`For waves in lossy media, which results are on the formula sheet and which are not?`,
      a: md`**On the sheet:** $\gamma$, $\eta$, $\tau = \tfrac12\tan^{-1}(\sigma/\omega\epsilon)$, $\eta\gamma = j\omega\mu$, $\gamma/\eta = \sigma + j\omega\epsilon$, the three ways back to $\sigma$, $\mu$, $\epsilon$, $\langle\mathbf S\rangle$, $\Gamma$, $\tau = 1 + \Gamma$, and the three limits (lossless, imperfect dielectric, good conductor). **Not on it:** $\delta$, $R_s$, dB, power fractions, radiation pressure, standing-wave fields.`,
      why: md`Know what to look up and what to carry: the second list goes on your notecard. The limits are approximations, so check $\sigma/\omega\epsilon$ first to pick the right row.` },
    { id: 'c3_rec_p3', cat: 'recall', t: 'What page 3 of the sheet gives you',
      q: md`For transmission lines, which results are on the formula sheet and which are not?`,
      a: md`**On the sheet:** telegrapher's equations, the bounce sums for $V(z, t)$ and $I(z, t)$, $Z_0$, $v_p$, $\tau_g$, $\Gamma_L$, $\Gamma_g$, $\tilde V(d)$, $\tilde I(d)$, $Z(d)$, $P(d)$, VSWR, $\tilde V(l)$ from the source, and the shorted and open $\tilde V(d)$, $Z(d)$, $Y(d)$. **Not on it:** GF values, $\mathcal L$ and $\mathcal C$ formulas, the steady state, junction coefficients, the $\lambda/4$ and $\lambda/2$ rules, resonance conditions.`,
      why: md`The "not" list is what many exam parts lean on: a coax $\mathcal L$, $\mathcal C$, $Z_0$, a two-line junction, a final value to check a bounce diagram. Put it on your notecard.` },
    { id: 'c3_rec_bouncesum', cat: 'recall', t: 'Reading the bounce sum on the sheet',
      q: md`The sheet's sum starts
        $$V = \tau_g\sum_n(\Gamma_L\Gamma_g)^n\delta\Big(t - \frac zv - n\frac{2l}v\Big) + \ldots$$
        What is the $n = 1$ term?`,
      a: md`A forward impulse of weight $\tau_g\Gamma_L\Gamma_g$, launched one round trip late: it passes $z$ at $t = z/v + 2l/v$. **On the sheet.**`,
      why: md`Each round trip multiplies by one $\Gamma_L$ and one $\Gamma_g$ and adds $2l/v$ of delay. The second sum holds the backward waves: one extra $\Gamma_L$, passing $z$ at $t = (n + 1)2l/v - z/v$. For a step input, replace $\delta$ by $u$: a staircase.` },
    { id: 'c3_rec_vswrG', cat: 'recall', t: md`From VSWR back to $|\Gamma|$`,
      q: md`Given the VSWR $s$, find $|\Gamma_L|$.`,
      a: md`$$|\Gamma_L| = \frac{s - 1}{s + 1}$$ **Not on the sheet**; invert the VSWR formula that is.`,
      why: md`$s(1 - |\Gamma|) = 1 + |\Gamma|$. Collect $|\Gamma|$: $|\Gamma|(s + 1) = s - 1$. VSWR 2 means $|\Gamma| = \tfrac13$; VSWR 3 means $\tfrac12$.`,
      ex: { expr: '(s-1)/(s+1)', vars: { s: [1.1, 10] } }, exWhat: '|Γ| using s' },

    // ================================================================ what if you change...
    { id: 'c3_wi_fgood', cat: 'what-if', t: 'Double the frequency: good conductor',
      q: md`A good conductor. You double $f$. What happens to $\alpha$, $\delta$, $|\eta|$, $\tau$ and $R_s$?`,
      a: md`$\alpha$, $|\eta|$ and $R_s$ grow by $\sqrt2$. $\delta$ shrinks by $\sqrt2$. $\tau$ stays $45°$.`,
      why: md`$\alpha = \sqrt{\pi f\mu\sigma}$, $|\eta| = \sqrt{\omega\mu/\sigma}$ and $R_s = \sqrt{\pi f\mu/\sigma}$ all go as $\sqrt f$. The angle comes from $\sqrt j$, which has no $f$ in it. Higher frequency: the current crowds into a thinner skin and the surface gets lossier.` },
    { id: 'c3_wi_fdiel', cat: 'what-if', t: 'Double the frequency: imperfect dielectric',
      q: md`An imperfect dielectric ($\sigma/\omega\epsilon\ll1$). You double $f$. What happens to $\alpha$, $\beta$ and $\tau$?`,
      a: md`$\alpha$ stays the same, $\beta$ doubles, $\tau$ halves.`,
      why: md`$\alpha\approx\frac\sigma2\sqrt{\mu/\epsilon}$ has no $\omega$. $\beta\approx\omega\sqrt{\mu\epsilon}$. $\tau\approx\sigma/2\omega\epsilon\propto1/\omega$. The loss per meter is fixed, but the loss per wavelength drops.` },
    { id: 'c3_wi_sgood', cat: 'what-if', t: md`Double $\sigma$: good conductor`,
      q: md`A good conductor. You double $\sigma$. What happens to $\delta$, $R_s$ and $|\eta|$?`,
      a: md`All three shrink by $\sqrt2$.`,
      why: md`$\delta = 1/\sqrt{\pi f\mu\sigma}$, $R_s = \sqrt{\pi f\mu/\sigma}$ and $|\eta| = \sqrt{\omega\mu/\sigma}$ all go as $\sigma^{-1/2}$. A better conductor has a thinner skin but less loss: $R_s = 1/(\sigma\delta)$, and $\sigma$ grows faster than $\delta$ shrinks.` },
    { id: 'c3_wi_sdiel', cat: 'what-if', t: md`Double $\sigma$: imperfect dielectric`,
      q: md`An imperfect dielectric. You double $\sigma$. What happens to $\alpha$, $\delta$ and $\tau$?`,
      a: md`$\alpha$ doubles, $\delta$ halves, $\tau$ doubles. $\beta$ and $|\eta|$ barely change.`,
      why: md`$\alpha\approx\tfrac12\sigma|\eta|$ and $\tau\approx\sigma/2\omega\epsilon$ are linear in $\sigma$. $\beta$ and $|\eta|$ only get corrections of order $(\sigma/\omega\epsilon)^2$.` },
    { id: 'c3_wi_eps', cat: 'what-if', t: md`Four times the $\epsilon_r$`,
      q: md`A lossless medium with $\mu = \mu_0$. You make $\epsilon_r$ four times larger at the same $f$. What happens to $v$, $\lambda$, $\beta$ and $\eta$?`,
      a: md`$v$, $\lambda$ and $\eta$ halve. $\beta$ doubles.`,
      why: md`$v = 1/\sqrt{\mu\epsilon}$ and $\eta = \sqrt{\mu/\epsilon}$ go as $\epsilon^{-1/2}$; $\beta = \omega\sqrt{\mu\epsilon}$ goes as $\epsilon^{1/2}$; $\lambda = v/f$. The frequency is set by the source and is the same in every medium.` },
    { id: 'c3_wi_len', cat: 'what-if', t: 'Double the line length',
      q: md`A step drives a line. You double its length. What changes: $\tau_g$, $\Gamma_L$, $\Gamma_g$, the final value, the times?`,
      a: md`Only the times: every arrival time doubles. $\tau_g$, $\Gamma_L$, $\Gamma_g$ and the final value stay the same.`,
      why: md`The coefficients depend only on $R_g$, $R_L$ and $Z_0$. The final value is the DC divider, with no length in it. Length only sets the delay $l/v$. (In a phasor problem, doubling $l$ doubles $\beta l$, and that changes everything.)` },
    { id: 'c3_wi_swap', cat: 'what-if', t: md`Swap $R_g$ and $R_L$`,
      q: md`You swap the source resistor and the load resistor. What happens to $\Gamma_L$, $\Gamma_g$, how fast the bounces die, and the final load voltage?`,
      a: md`$\Gamma_L$ and $\Gamma_g$ swap. Their product, which sets how fast the bounces shrink, is unchanged. The final load voltage changes from $V_g\frac{R_L}{R_g + R_L}$ to $V_g\frac{R_g}{R_g + R_L}$, and $\tau_g$ changes too.`,
      why: md`Each round trip multiplies by $\Gamma_L\Gamma_g$, which does not care which is which. But the launch $\tau_g = Z_0/(R_g + Z_0)$ and the DC divider both care where each resistor sits.` },
    { id: 'c3_wi_matchg', cat: 'what-if', t: md`Make $R_g = Z_0$`,
      q: md`The source resistor equals $Z_0$. What does the bounce diagram look like, and when does the load voltage reach its final value?`,
      a: md`$\tau_g = \tfrac12$ and $\Gamma_g = 0$: one wave out, one echo back, and the source absorbs the echo. The load voltage is final from its first arrival, $t = l/v$; the source end settles at $t = 2l/v$.`,
      why: md`$\Gamma_g = (Z_0 - Z_0)/(2Z_0) = 0$. The load voltage $\tfrac12V_g(1 + \Gamma_L) = V_g\frac{R_L}{R_L + Z_0}$ is already the DC divider, because $R_g = Z_0$.` },
    { id: 'c3_wi_matchL', cat: 'what-if', t: md`Make $R_L = Z_0$`,
      q: md`The load equals $Z_0$. What do you see along the line after a step?`,
      a: md`One front travels to the load and stops there. Behind it the line sits at $\tau_gV_g = V_g\frac{Z_0}{R_g + Z_0}$, already the DC answer. No reflections at all.`,
      why: md`$\Gamma_L = 0$, so nothing comes back and $\Gamma_g$ never acts. A matched load looks like an endless line.` },
    { id: 'c3_wi_open', cat: 'what-if', t: 'A step reaches an open end',
      q: md`A voltage step $V^+$ reaches an open end. What are $V$ and $I$ at the end right after it arrives?`,
      a: md`$\Gamma_L = +1$: the voltage at the end jumps to $2V^+$, twice the incident step. The current stays 0.`,
      why: md`Voltages add: $V^+ + V^+$. Currents cancel: $V^+/Z_0 - V^+/Z_0 = 0$, as an open demands. The reflected wave carries the news "stop" back toward the source.` },
    { id: 'c3_wi_short', cat: 'what-if', t: 'A step reaches a short',
      q: md`A voltage step $V^+$ reaches a shorted end. What are $V$ and $I$ at the end right after it arrives?`,
      a: md`$\Gamma_L = -1$: the voltage at the end stays 0, and the current jumps to $2V^+/Z_0$, twice the incident current.`,
      why: md`$V^+ - V^+ = 0$, and $V^+/Z_0 - (-V^+)/Z_0 = 2V^+/Z_0$. A backward wave with negative voltage carries positive current.` },
    { id: 'c3_wi_Rg0', cat: 'what-if', t: md`An ideal source, $R_g = 0$`,
      q: md`$R_g = 0$. What are $\tau_g$ and $\Gamma_g$, and what happens to a wave that comes back to the source?`,
      a: md`$\tau_g = 1$ (all of $V_g$ is launched) and $\Gamma_g = -1$: each returning wave bounces off with its sign flipped, so the source end stays at $V_g$.`,
      why: md`An ideal voltage source pins $V(0, t) = V_g$, so any arriving wave must be cancelled there by an equal and opposite one. With $\Gamma_L = \tfrac13$, the steps at the middle of the line go $1, \tfrac13, -\tfrac13, -\tfrac19, \tfrac19, \ldots$ times $V_g$.` },
    { id: 'c3_wi_gap', cat: 'what-if', t: 'Double the plate gap',
      q: md`Parallel-plate line. You double the gap $d$ and keep $W$. What happens to $\mathcal L$, $\mathcal C$, $Z_0$ and $v$?`,
      a: md`$\mathcal L$ doubles, $\mathcal C$ halves, $Z_0$ doubles, $v$ stays the same.`,
      why: md`$\mathcal L = \mu d/W$ and $\mathcal C = \epsilon W/d$. $Z_0 = \sqrt{\mathcal L/\mathcal C} = \eta d/W$. $v = 1/\sqrt{\mathcal{LC}} = 1/\sqrt{\mu\epsilon}$ has no geometry in it.` },
    { id: 'c3_wi_fill', cat: 'what-if', t: md`Fill an air coax with $\epsilon_r = 4$`,
      q: md`An air-filled coax is refilled with a dielectric of $\epsilon_r = 4$. What happens to $\mathcal C$, $\mathcal L$, $Z_0$ and $v$?`,
      a: md`$\mathcal C$ becomes 4 times larger, $\mathcal L$ stays the same, $Z_0$ halves, $v$ halves (to $c/2$).`,
      why: md`$\mathcal C = \epsilon\,\text{GF}$ and $\mathcal L = \mu/\text{GF}$ has no $\epsilon$. $Z_0 = \sqrt{\mathcal L/\mathcal C}$ and $v = 1/\sqrt{\mathcal{LC}}$ both fall by $\sqrt4 = 2$.` },
    { id: 'c3_wi_Z2v2', cat: 'what-if', t: md`Line 2 has twice the $Z_0$ and twice the $v$`,
      q: md`Compared with line 1, line 2 has $Z_2 = 2Z_1$ and $v_2 = 2v_1$. Find $\mathcal L_2$ and $\mathcal C_2$.`,
      a: md`$\mathcal L_2 = \mathcal L_1$ and $\mathcal C_2 = \mathcal C_1/4$.`,
      why: md`$\mathcal L = Z_0/v$ and $\mathcal C = 1/(Z_0v)$. The ratio $Z_0/v$ is unchanged; the product $Z_0v$ is 4 times bigger.` },
    { id: 'c3_wi_qwf', cat: 'what-if', t: 'Run a quarter-wave match at twice the frequency',
      q: md`A section is $\lambda/4$ long at $f_0$ and matches $Z_L$ to the source. You drive it at $2f_0$. What is $Z_{in}$ now?`,
      a: md`At $2f_0$ the section is $\lambda/2$ long, so $Z_{in} = Z_L$: the match is gone.`,
      why: md`The electrical length $\beta l = 2\pi fl/v$ doubles, from $\pi/2$ to $\pi$. A quarter-wave match works only near its design frequency (and again at $3f_0$, $5f_0$, ...).` },
    { id: 'c3_wi_qwZL', cat: 'what-if', t: 'Double the load behind a quarter-wave line',
      q: md`Behind a $\lambda/4$ line you double $Z_L$. What happens to $Z_{in}$, and to the load current for a fixed $\tilde V_{in}$?`,
      a: md`$Z_{in}$ halves. The load current stays the same, $\tilde I_L = -j\tilde V_{in}/Z_0$, so the load voltage doubles.`,
      why: md`$Z_{in} = Z_0^2/Z_L$ is an inverter. Current forcing has no $Z_L$ in it: a quarter-wave line turns a voltage source into a current source.` },
    { id: 'c3_wi_stublen', cat: 'what-if', t: md`Shorted stub: $\lambda/8\to3\lambda/8$`,
      q: md`A shorted stub is $\lambda/8$ long. You make it $3\lambda/8$. What is its input impedance before and after?`,
      a: md`Before: $jZ_0$, an inductor. After: $-jZ_0$, a capacitor.`,
      why: md`$\beta d = \pi/4$ gives $\tan = 1$; $\beta d = 3\pi/4$ gives $\tan = -1$. Past $\lambda/4$ the short has turned into an open, and a stub just past an open acts like a capacitor.` },
    { id: 'c3_wi_Gflip', cat: 'what-if', t: md`Flip the sign of $\Gamma_L$`,
      q: md`$\Gamma_L$ changes from $+\tfrac13$ to $-\tfrac13$. What happens to the VSWR and to the standing-wave pattern?`,
      a: md`The VSWR stays 2. The pattern shifts by $\lambda/4$: maxima and minima trade places, and the load now sits at a voltage minimum instead of a maximum.`,
      why: md`VSWR depends only on $|\Gamma_L|$. $|1 + \Gamma(d)|$ is largest where $\Gamma(d)$ is real and positive. Flipping the sign turns $\Gamma(d)$ by half a turn, and since it turns by $2\beta d$, that is $d = \lambda/4$.` },
    { id: 'c3_wi_phase', cat: 'what-if', t: md`Put the $y$ part $90°$ behind`,
      q: md`$\tilde{\mathbf E} = (\hat x + \hat y)E_0e^{-j\beta z}$ is linearly polarized. You change the $y$ part to $-jE_0$. What polarization now?`,
      a: md`Circular, right-handed: $(\hat x - j\hat y)E_0e^{-j\beta z}$.`,
      why: md`At $z = 0$: $\mathbf E = E_0(\hat x\cos\omega t + \hat y\sin\omega t)$, equal sizes and $90°$ apart, turning from $x$ toward $y$. Thumb along $+z$: the right hand curls from $x$ to $y$. Unequal sizes, or a phase other than $0$, $\pm90°$, $180°$, would give an ellipse.` },
    { id: 'c3_wi_reverse', cat: 'what-if', t: 'Reverse the direction, keep the vector',
      q: md`$(\hat x - j\hat y)e^{-j\beta z}$ is right-handed. What is $(\hat x - j\hat y)e^{+j\beta z}$?`,
      a: md`Left-handed. At any fixed point it turns the same way in the $xy$ plane, but it travels toward $-z$.`,
      why: md`At $z = 0$ both are $\hat x\cos\omega t + \hat y\sin\omega t$, turning from $x$ to $y$. With the thumb along $-z$, it is the left hand whose fingers curl from $x$ to $y$. Handedness is rotation measured against the direction of travel.` },
    { id: 'c3_wi_absorb', cat: 'what-if', t: 'Absorber instead of mirror',
      q: md`You replace a perfect mirror by a perfect absorber. What happens to the radiation pressure? And what if you then double $E_0$?`,
      a: md`The pressure halves. Doubling $E_0$ then multiplies it by 4.`,
      why: md`Absorber: $\langle S\rangle/c$; mirror: $2\langle S\rangle/c$. Pressure follows power, and power goes as $|E_0|^2$.` },
    { id: 'c3_wi_pec', cat: 'what-if', t: 'Region 2 becomes a perfect conductor',
      q: md`What happens to $\Gamma$, $\tau$ and the field in region 1 as $\sigma_2\to\infty$?`,
      a: md`$\eta_2\to0$, so $\Gamma\to-1$ and $\tau\to0$. Region 1 holds a pure standing wave with an $E$ node at the surface, and no power gets in.`,
      why: md`$\Gamma = (0 - \eta_1)/(0 + \eta_1) = -1$. A real metal is close to this: $|\eta_2|$ of copper at 1 GHz is about $0.01\ \Omega$, against $377\ \Omega$ for air.` },

    // ================================================================ signs and directions
    { id: 'c3_sg_dir', cat: 'sign', t: 'Which way does it travel?',
      q: md`With the $e^{j\omega t}$ convention, which way do $e^{-j\beta z}$ and $e^{+j\beta z}$ travel?`,
      a: md`$e^{-j\beta z}$ toward $+z$. $e^{+j\beta z}$ toward $-z$.`,
      why: md`Back in time, $e^{-j\beta z}$ is $\cos(\omega t - \beta z)$. A crest has $\omega t - \beta z = 0$, so $z = (\omega/\beta)t$ grows with $t$. The same rule works on any axis: $e^{j\beta x}$ goes toward $-x$.` },
    { id: 'c3_sg_EH', cat: 'sign', t: md`$\tilde{\mathbf H}$ from $\tilde{\mathbf E}$`,
      q: md`$\tilde{\mathbf E} = \hat yE_0e^{-j\beta x}$ in a lossless medium. What is $\tilde{\mathbf H}$?`,
      a: md`$\tilde{\mathbf H} = \hat z\,(E_0/\eta)\,e^{-j\beta x}$.`,
      why: md`The rule: $\hat e\times\hat h$ = direction of travel, here $+\hat x$. Since $\hat y\times\hat z = \hat x$, $\hat h = \hat z$. Size: divide by $\eta$ (in a lossy medium the factor $e^{-j\tau}$ comes along).` },
    { id: 'c3_sg_back', cat: 'sign', t: md`The backward wave's $\mathbf H$`,
      q: md`$\tilde{\mathbf E} = \hat xE_0e^{+j\beta z}$. What is $\tilde{\mathbf H}$?`,
      a: md`$\tilde{\mathbf H} = -\hat y\,(E_0/\eta)\,e^{+j\beta z}$.`,
      why: md`It travels toward $-z$, so $\hat e\times\hat h$ must be $-\hat z$: $\hat x\times(-\hat y) = -\hat z$. This minus sign is why the $H$ boundary condition reads $(1 - \Gamma)/\eta_1 = \tau/\eta_2$.` },
    { id: 'c3_sg_Hr', cat: 'sign', t: 'Reflected current and reflected H',
      q: md`If the reflected voltage (or $E$) ratio is $\Gamma$, what is the reflected current (or $H$) ratio?`,
      a: md`$-\Gamma$.`,
      why: md`A backward wave has $I = -V/Z_0$ (and its $\mathbf H$ flipped). So at an open, $\Gamma = +1$ doubles $V$ and cancels $I$; at a short, $\Gamma = -1$ cancels $V$ and doubles $I$.` },
    { id: 'c3_sg_Gsign', cat: 'sign', t: md`The sign of $\Gamma$ at a glance`,
      q: md`When is $\Gamma$ positive, and when negative?`,
      a: md`Positive when the wave goes into a higher impedance ($\eta_2 > \eta_1$, or $R_L > Z_0$). Negative into a lower one. An open: $+1$. A short: $-1$.`,
      why: md`$\Gamma = (Z_2 - Z_1)/(Z_2 + Z_1)$. Air into glass ($\eta$ drops): negative, so the reflected $E$ is flipped. Glass into air: positive.` },
    { id: 'c3_sg_sheetE', cat: 'sign', t: md`A current sheet's $\mathbf E$`,
      q: md`A sheet carries $\mathbf J_s = \hat xJ_0\cos\omega t$ on $z = 0$ in a medium $\eta$. Which way does $\mathbf E$ point at the sheet, compared with $\mathbf J_s$, and how big is it?`,
      a: md`Opposite to $\mathbf J_s$: $\mathbf E(0, t) = -\hat x\,\frac\eta2J_0\cos\omega t$, the same on both sides.`,
      why: md`The sheet delivers power, so $\mathbf J_s\cdot\mathbf E < 0$. Check: the injected power $-\langle\mathbf J_s\cdot\mathbf E\rangle = \eta J_0^2/4$ equals the two waves' power, $\eta J_0^2/8$ each.` },
    { id: 'c3_sg_Hsheet', cat: 'sign', t: md`A current sheet's $\mathbf H$`, figHtml: sheetFig(),
      q: md`The sheet carries $\mathbf J_s = \hat xJ_s$ (into the page, $J_s > 0$). Which way does $\mathbf H$ point for $z > 0$, and for $z < 0$?`,
      a: md`$z > 0$: along $-\hat y$ (down). $z < 0$: along $+\hat y$ (up).`,
      why: md`$\mathbf E$ is along $-\hat x$ on both sides, and each wave's $\mathbf E\times\mathbf H$ must point away from the sheet: $(-\hat x)\times(-\hat y) = +\hat z$ and $(-\hat x)\times\hat y = -\hat z$. Check the boundary condition: $\hat z\times(\mathbf H^+ - \mathbf H^-) = \hat z\times(-\hat yJ_s) = \hat xJ_s$.` },
    { id: 'c3_sg_lead', cat: 'sign', t: 'Reading the rotation from a phasor',
      q: md`At a fixed point, $\tilde{\mathbf E} = \hat x + j\hat y$. Which way does $\mathbf E$ turn?`,
      a: md`From $+y$ toward $+x$. $\mathbf E(t) = \hat x\cos\omega t - \hat y\sin\omega t$ points along $+y$ a quarter period before it points along $+x$.`,
      why: md`$+j$ means the $y$ part leads by $90°$, so it peaks first: the vector turns from the leading component toward the lagging one. Then match a hand to the direction of travel: toward $+z$ this is left-handed, toward $-z$ right-handed.` },
    { id: 'c3_sg_hand2', cat: 'sign', t: md`Handedness of a wave along $x$`,
      q: md`$\tilde{\mathbf E} = (\hat z + j\hat y)e^{j\beta x}$. Direction of travel, and handedness?`,
      a: md`It travels toward $-x$ and is left-handed.`,
      why: md`$e^{+j\beta x}$: toward $-x$. The $y$ part leads ($+j$), so $\mathbf E$ turns from $y$ toward $z$. With the right thumb along $-x$ the fingers curl from $z$ toward $y$ (since $\hat z\times\hat y = -\hat x$), the wrong way. So it is left-handed.` },
    { id: 'c3_sg_handfig', cat: 'sign', t: 'Handedness from a picture', figHtml: rotFig(),
      q: md`The figure shows the tip of $\mathbf E$ at one point, turning counterclockwise on the page. The wave travels into the page. Right- or left-handed?`,
      a: md`Left-handed.`,
      why: md`Point a thumb into the page. Your right hand then curls clockwise as you see it; your left hand curls counterclockwise, matching the picture. With $x$ right and $y$ up, into the page is $-z$, and the field is $(\hat x - j\hat y)e^{+j\beta z}$.` },
    { id: 'c3_sg_envfig', cat: 'sign', t: md`Read $\Gamma$ off an envelope`, figHtml: envFig(),
      q: md`The plot shows $|\tilde E|$ in front of an interface at $z = 0$ (region 2 to the right). Both media are lossless. What is $\Gamma$, and is $\eta_2$ bigger or smaller than $\eta_1$?`,
      a: md`$\Gamma = -\tfrac12$, so $\eta_2 = \eta_1/3$: smaller.`,
      why: md`$|\Gamma| = \frac{1.5 - 0.5}{1.5 + 0.5} = \tfrac12$. A minimum sits at the boundary, so the reflected wave arrives there flipped: $\Gamma < 0$. Then $\frac{\eta_2 - \eta_1}{\eta_2 + \eta_1} = -\tfrac12$ gives $\eta_2 = \eta_1/3$. The flat line is the transmitted wave, $|\tau|E_0 = 0.5E_0$, continuous with region 1.` },
    { id: 'c3_sg_tau', cat: 'sign', t: md`Does $H$ lead or lag $E$?`,
      q: md`In a lossy medium, $\eta = |\eta|e^{j\tau}$. Does $H$ lead or lag $E$ in time, and by how much at most?`,
      a: md`$H$ lags $E$ by $\tau$, which is between $0$ and $45°$.`,
      why: md`$\tilde H = \tilde E/\eta = (\tilde E/|\eta|)e^{-j\tau}$: the phase of $H$ is the phase of $E$ minus $\tau$. $\tau > 0$ because $\eta^2 = j\omega\mu/(\sigma + j\omega\epsilon)$ divides a $90°$ angle by one smaller than $90°$ once $\sigma > 0$.` },
    { id: 'c3_sg_sin', cat: 'sign', t: 'The phasor of a sine',
      q: md`What is the phasor of $\sin(\omega t - \beta z)$? Of $-\sin(\omega t + \beta z)$?`,
      a: md`$-je^{-j\beta z}$ and $+je^{+j\beta z}$.`,
      why: md`Cosine is the reference: $\sin x = \cos(x - 90°)$ and $e^{-j90°} = -j$. A minus sign is $e^{j180°}$, so $-(-j) = +j$. Check: $\Re\{-je^{j\theta}\} = \Re\{-j\cos\theta + \sin\theta\} = \sin\theta$.` },
    { id: 'c3_sg_tel', cat: 'sign', t: "The minus signs in the telegrapher's equations",
      q: md`Why is there a minus sign in $-\partial V/\partial z = \mathcal L\,\partial I/\partial t$?`,
      a: md`Wherever the current is growing, the voltage drops along the line in the direction of the current, as across an inductor: $V(z) - V(z + \Delta z) = \mathcal L\Delta z\,\partial I/\partial t$.`,
      why: md`Each short piece $\Delta z$ is a series inductor $\mathcal L\Delta z$ and a shunt capacitor $\mathcal C\Delta z$. KVL across the inductor gives the first equation. KCL at the capacitor node, $I(z) - I(z + \Delta z) = \mathcal C\Delta z\,\partial V/\partial t$, gives the second.` },
    { id: 'c3_sg_d', cat: 'sign', t: md`The direction of $d$`,
      q: md`In the phasor line formulas, where is $d = 0$, and which way does $d$ grow? Which way does $\Gamma(d)$ turn as $d$ grows?`,
      a: md`$d = 0$ at the load, and $d$ grows toward the generator. $\Gamma(d) = \Gamma_Le^{-j2\beta d}$ turns clockwise (its angle decreases) as you move toward the generator.`,
      why: md`$d = -z$ with the load at $z = 0$, so $e^{j\beta d}$ is the wave heading for the load. Time-domain problems put $z = 0$ at the generator instead: check which one a problem uses.` },
    { id: 'c3_sg_stubX', cat: 'sign', t: 'Inductive or capacitive?',
      q: md`A shorted stub of length $d$. For which lengths is it inductive, and for which capacitive?`,
      a: md`Inductive ($+jX$) for $0 < d < \lambda/4$. Capacitive ($-jX$) for $\lambda/4 < d < \lambda/2$. Then it repeats every $\lambda/2$. An open stub is the other way round.`,
      why: md`$Z = jZ_0\tan\beta d$, and $\tan$ is positive from $0$ to $\pi/2$ and negative from $\pi/2$ to $\pi$. Positive reactance is $j\omega L$; negative is $1/(j\omega C) = -j/(\omega C)$.` },
    { id: 'c3_sg_Gg', cat: 'sign', t: md`The sign of $\Gamma_g$`,
      q: md`$R_g < Z_0$. What sign is $\Gamma_g$, and what does that do to a wave returning to the source?`,
      a: md`$\Gamma_g < 0$: the re-launched wave has the opposite sign of the one that arrived. ($R_g = 0$ gives $\Gamma_g = -1$.)`,
      why: md`$\Gamma_g = (R_g - Z_0)/(R_g + Z_0)$, the load formula with $R_g$ in place of $R_L$. If $\Gamma_L > 0$ and $\Gamma_g < 0$, the steps alternate in sign and the staircase rings around its final value.` },
    { id: 'c3_sg_JE', cat: 'sign', t: md`$\mathbf J\cdot\mathbf E$ inside a conductor`,
      q: md`A wave in a conducting medium. Is $\langle\mathbf J\cdot\mathbf E\rangle$ positive or negative there, and where does that power come from?`,
      a: md`Positive: $\langle\mathbf J\cdot\mathbf E\rangle = \tfrac12\sigma|\tilde E|^2$, heat. It comes out of the wave, whose $\langle S\rangle$ falls as $e^{-2\alpha z}$.`,
      why: md`$\mathbf J = \sigma\mathbf E$ points along $\mathbf E$, so the product is $\sigma E^2\ge0$. Averaged, the Poynting theorem reads $\nabla\cdot\langle\mathbf S\rangle = -\langle\mathbf J\cdot\mathbf E\rangle$, so the power flow must shrink with depth.` },
    { id: 'c3_sg_Sr', cat: 'sign', t: 'Which way the reflected power flows',
      q: md`A wave hits an interface from $z < 0$. Which way does $\langle\mathbf S_r\rangle$ point, and what is the net power flow in a lossless region 1?`,
      a: md`$\langle\mathbf S_r\rangle$ points along $-\hat z$. Net flow in region 1: $(1 - |\Gamma|^2)\langle S_i\rangle$ along $+\hat z$, equal to the transmitted power.`,
      why: md`The reflected wave travels toward $-z$, so its $\mathbf E\times\mathbf H$ does too. With real $\eta_1$, the cross terms between the incident and reflected waves are purely imaginary, so the two powers simply subtract.` },

    // ================================================================ numbers without a calculator
    { id: 'c3_nm_const', cat: 'numbers', t: 'The four constants',
      q: md`$\eta_0$, $\mu_0$, $\epsilon_0$ and $c$, in the forms that cancel nicely?`,
      a: md`$\eta_0 = 120\pi\approx377\ \Omega$, $\mu_0 = 4\pi\times10^{-7}$ H/m, $\epsilon_0 = \frac{10^{-9}}{36\pi}$ F/m, $c = 3\times10^8$ m/s.`,
      why: md`They are tied together: $c = 1/\sqrt{\mu_0\epsilon_0}$ and $\eta_0 = \sqrt{\mu_0/\epsilon_0} = \mu_0c$. Check: $4\pi\times10^{-7}\times3\times10^8 = 120\pi$. Keep $\pi$ as a symbol; it usually cancels.` },
    { id: 'c3_nm_c', cat: 'numbers', t: 'The speed of light in handy units',
      q: md`$c$ in m/µs and in cm/ns? The wavelength in air at 300 MHz, 1 GHz and 100 MHz?`,
      a: md`$c = 300$ m/µs $= 30$ cm/ns. $\lambda = 1$ m at 300 MHz, 30 cm at 1 GHz, 3 m at 100 MHz.`,
      why: md`$\lambda = c/f$. For bounce diagrams in µs: a 300 m air line has a 1 µs delay, and a line at $c/2$ takes 1 µs per 150 m.` },
    { id: 'c3_nm_weps', cat: 'numbers', t: md`$\omega\epsilon_0$ in your head`,
      q: md`What is $\omega\epsilon_0$ at $f = 1$ GHz? What quick rule does it give for the loss tangent?`,
      a: md`$\omega\epsilon_0 = \frac{2\pi\times10^9\times10^{-9}}{36\pi} = \frac1{18}$ S/m. So
        $$\frac{\sigma}{\omega\epsilon} = \frac{18\,\sigma}{\epsilon_r\,f_{\text{GHz}}}$$`,
      why: md`The $\pi$ cancels and $10^9\times10^{-9} = 1$. Example: $\sigma = 10^{-3}$ S/m, $\epsilon_r = 4$, 1 GHz gives $18\times10^{-3}/4 = 4.5\times10^{-3}$: an imperfect dielectric. Seawater at 1 kHz gives about $10^6$: a good conductor.` },
    { id: 'c3_nm_alpha', cat: 'numbers', t: md`$\sqrt{\pi f\mu_0\sigma}$ fast`,
      q: md`A quick way to estimate $\alpha = \sqrt{\pi f\mu_0\sigma}$ in your head?`,
      a: md`$\pi\mu_0 = 4\pi^2\times10^{-7}\approx4\times10^{-6}$, so
        $$\alpha\approx2\times10^{-3}\sqrt{f\sigma}\ \text{m}^{-1}$$`,
      why: md`$\pi^2\approx10$ (within 1.3%). Seawater ($\sigma = 4$ S/m) at 1 kHz: $2\times10^{-3}\sqrt{4000}\approx0.126$ per meter. Exactly: $\sqrt{16\pi^2\times10^{-4}} = \pi/25$ per meter, so $\delta = 25/\pi\approx7.96$ m.` },
    { id: 'c3_nm_exp', cat: 'numbers', t: 'Exponentials to know',
      q: md`$e^{-1}$, $e^{-2}$, $e^{-\pi}$, $e^{-2\pi}$?`,
      a: md`$0.37$, $0.135$, $0.043$, $0.0019$.`,
      why: md`$e^{-1}$: the field after one skin depth. $e^{-2}$: the power after one skin depth. $e^{-2\pi}$: the field after one wavelength in a good conductor ($\lambda = 2\pi\delta$): a good conductor kills a wave within a wavelength.` },
    { id: 'c3_nm_dB', cat: 'numbers', t: 'Nepers and decibels',
      q: md`How many dB is one neper? How many dB does a wave lose per skin depth?`,
      a: md`1 Np $= 8.686$ dB, so one skin depth costs $8.7$ dB (power down to $13.5\%$).`,
      why: md`Field ratio $e^{-1}$: $20\log_{10}e = 8.686$. Power ratio $e^{-2}$: $10\log_{10}e^2$, the same number. Three skin depths cost about 26 dB.` },
    { id: 'c3_nm_cu', cat: 'numbers', t: 'Skin depth of copper',
      q: md`Copper ($\sigma\approx5.8\times10^7$ S/m): the skin depth at 60 Hz, 1 MHz and 1 GHz?`,
      a: md`About 8.5 mm, 66 µm and 2.1 µm.`,
      why: md`$\delta\propto1/\sqrt f$: every factor of 1000 in frequency shrinks $\delta$ by $\sqrt{1000}\approx32$. That is why high-frequency current lives on the surface, and why $R_s$ (about $8\ \text{m}\Omega$ at 1 GHz) sets the loss.` },
    { id: 'c3_nm_sea', cat: 'numbers', t: 'Seawater numbers',
      q: md`Seawater: $\sigma = 4$ S/m, $\epsilon_r = 81$. Where is $\sigma/\omega\epsilon = 1$? What is the skin depth at 1 kHz?`,
      a: md`$\sigma/\omega\epsilon = 1$ near 0.9 GHz; far below that, seawater is a good conductor. At 1 kHz: $\delta = 25/\pi\approx8$ m.`,
      why: md`$\sigma/\omega\epsilon = 18\sigma/(\epsilon_rf_{\text{GHz}}) = 72/(81f_{\text{GHz}})$, which is 1 at $f\approx0.89$ GHz. That is why submarines are reached at very low frequencies: $\delta\propto1/\sqrt f$.` },
    { id: 'c3_nm_etas', cat: 'numbers', t: md`$\eta$ of common dielectrics`,
      q: md`$\eta$ for $\mu = \mu_0$ and $\epsilon_r = 4$, $9$ and $2.25$?`,
      a: md`$60\pi\approx188\ \Omega$, $40\pi\approx126\ \Omega$, $80\pi\approx251\ \Omega$.`,
      why: md`$\eta = \eta_0/\sqrt{\epsilon_r}$: divide $120\pi$ by 2, 3 and 1.5. The same $\sqrt{\epsilon_r}$ divides the speed: $c/2$, $c/3$, $2c/3$.` },
    { id: 'c3_nm_G', cat: 'numbers', t: 'Reflections off dielectrics',
      q: md`From air onto $\epsilon_r = 4$, and from air onto $\epsilon_r = 9$: $\Gamma$, and the fraction of the power reflected?`,
      a: md`$\epsilon_r = 4$: $\Gamma = -\tfrac13$, $\tfrac19$ of the power reflected, $\tfrac89$ transmitted. $\epsilon_r = 9$: $\Gamma = -\tfrac12$, $\tfrac14$ reflected.`,
      why: md`With $\eta_2 = \eta_1/\sqrt{\epsilon_r}$, $\Gamma = (1 - \sqrt{\epsilon_r})/(1 + \sqrt{\epsilon_r})$. For 4: $(1 - 2)/3$. For 9: $(1 - 3)/4$. The power reflected is $\Gamma^2$.` },
    { id: 'c3_nm_GL', cat: 'numbers', t: 'Line reflections to know',
      q: md`A $50\ \Omega$ line into $100\ \Omega$, into $25\ \Omega$, into $150\ \Omega$? A $150\ \Omega$ line into $50\ \Omega$?`,
      a: md`$\tfrac13$, $-\tfrac13$, $\tfrac12$; and $-\tfrac12$.`,
      why: md`$(R - Z_0)/(R + Z_0)$: $50/150$, $-25/75$, $100/200$, $-100/200$. Doubling or halving the impedance always gives $\pm\tfrac13$; tripling or dividing by 3 gives $\pm\tfrac12$.` },
    { id: 'c3_nm_vswr', cat: 'numbers', t: 'VSWR values to know',
      q: md`The VSWR for $|\Gamma| = \tfrac15$, $\tfrac13$ and $\tfrac12$?`,
      a: md`$1.5$, $2$ and $3$.`,
      why: md`$(1 + |\Gamma|)/(1 - |\Gamma|)$: $\frac{6/5}{4/5}$, $\frac{4/3}{2/3}$, $\frac{3/2}{1/2}$. Shortcut: a resistive load has VSWR $= R_L/Z_0$ or $Z_0/R_L$, whichever is above 1.` },
    { id: 'c3_nm_tauang', cat: 'numbers', t: md`Values of the angle $\tau$`,
      q: md`$\tau = \tfrac12\tan^{-1}(\sigma/\omega\epsilon)$ when $\sigma/\omega\epsilon = 1/\sqrt3$, $1$, $\sqrt3$, and very large?`,
      a: md`$15°$, $22.5°$, $30°$ and $45°$.`,
      why: md`$\tan^{-1}$ of those is $30°$, $45°$, $60°$ and $90°$; halve each. Exams like $\sigma/\omega\epsilon = 1$ or $\sqrt3$ for exactly this reason.` },
    { id: 'c3_nm_tan', cat: 'numbers', t: 'Stub reactances to know',
      q: md`A shorted stub, $jZ_0\tan\beta d$, at $\beta d = 30°$, $45°$ and $60°$ (that is, $d = \lambda/12$, $\lambda/8$, $\lambda/6$)?`,
      a: md`$jZ_0/\sqrt3\approx j0.577Z_0$, then $jZ_0$, then $j\sqrt3Z_0\approx j1.73Z_0$.`,
      why: md`$\beta d = 2\pi d/\lambda$, so $\lambda/8$ is $\pi/4$. $\tan30° = 1/\sqrt3$ and $\tan60° = \sqrt3$. An open stub, $-jZ_0\cot\beta d$, gives the same three sizes in reverse order, with a minus sign.` },
    { id: 'c3_nm_cx', cat: 'numbers', t: 'Complex arithmetic to know cold',
      q: md`$1/j$, $1/(1 + j)$, $|1 + j|$, $\sqrt j$, $e^{j\pi/2}$, $e^{j\pi}$?`,
      a: md`$-j$, $\tfrac12(1 - j)$, $\sqrt2$, $(1 + j)/\sqrt2$, $j$, $-1$.`,
      why: md`$1/j = j/j^2 = -j$. Multiply by the conjugate: $\frac{1 - j}{(1 + j)(1 - j)} = \frac{1 - j}{2}$. $\sqrt j = e^{j45°}$ is the good conductor's $(1 + j)$. Quarter and half waves are $e^{j\pi/2}$ and $e^{j\pi}$.` },
    { id: 'c3_nm_coax', cat: 'numbers', t: 'Coax impedance numbers',
      q: md`Air coax: $Z_0$ when $b/a = e$? When $b/a = e^2$? Filled with $\epsilon_r = 4$ and $b/a = e$?`,
      a: md`$60\ \Omega$, $120\ \Omega$ and $30\ \Omega$.`,
      why: md`$Z_0 = \frac{\eta}{2\pi}\ln\frac ba = \frac{60}{\sqrt{\epsilon_r}}\ln\frac ba$. Problems pick $b/a = e$ so that the log is 1. Also useful: $\ln2\approx0.69$, $\ln10\approx2.3$.` },
    { id: 'c3_nm_qw', cat: 'numbers', t: 'Quarter-wave matches',
      q: md`$Z_0$ of a quarter-wave section that matches $200\ \Omega$ to $50\ \Omega$? $72\ \Omega$ to $50\ \Omega$?`,
      a: md`$100\ \Omega$ and $60\ \Omega$.`,
      why: md`$Z_0 = \sqrt{Z_{in}Z_L}$: $\sqrt{10^4} = 100$ and $\sqrt{3600} = 60$. The section's impedance is the geometric mean, always between the two.` },
    { id: 'c3_nm_pp', cat: 'numbers', t: 'A parallel-plate line',
      q: md`Air parallel plates with $d = 1$ mm and $W = 1$ cm: $Z_0$? The same plates filled with $\epsilon_r = 4$?`,
      a: md`$12\pi\approx37.7\ \Omega$; then $6\pi\approx18.8\ \Omega$.`,
      why: md`$Z_0 = \eta d/W = 120\pi\times0.1$. The dielectric divides $\eta$ by $\sqrt{\epsilon_r} = 2$.` },
    { id: 'c3_nm_ss', cat: 'numbers', t: 'A bounce problem in your head',
      q: md`$V_g = 10$ V step, $R_g = 25\ \Omega$, $Z_0 = 50\ \Omega$, $R_L = 100\ \Omega$. The first step launched, $\Gamma_L$, $\Gamma_g$, and the final load voltage?`,
      a: md`$\tau_g = \tfrac23$, so $\tfrac{20}{3}$ V is launched. $\Gamma_L = \tfrac13$, $\Gamma_g = -\tfrac13$. Final: $10\times\tfrac{100}{125} = 8$ V.`,
      why: md`The first load voltage is $\tfrac{20}{3}(1 + \tfrac13) = \tfrac{80}{9}\approx8.9$ V, above the final 8 V; the $\Gamma_g < 0$ bounce then pulls it back down. Check with the series: $\tfrac{20}{3}\cdot\frac{4/3}{1 + 1/9} = 8$ V.` },
    { id: 'c3_nm_pres', cat: 'numbers', t: 'How big is radiation pressure?',
      q: md`Sunlight-sized intensity, $1\ \text{kW/m}^2$, on a perfect mirror. The pressure?`,
      a: md`$\frac{2\times10^3}{3\times10^8}\approx6.7\times10^{-6}$ Pa.`,
      why: md`$2\langle S\rangle/c$, and $c$ is huge: light pushes, but gently. Units: $\text{W/m}^2$ divided by $\text{m/s}$ is $\text{N/m}^2$, a pascal.` },
  ];

  // card text may be indented in the source; the markdown must not be (an indented "|" or "!!" line changes meaning)
  const NL = String.fromCharCode(10), BR = NL + NL;
  const tidy = (s) => String(s).replace(/\n[ \t]+/g, NL).trim();
  const seen = new Set();
  CARDS.forEach((c) => {
    c.q = tidy(c.q); c.a = tidy(c.a); c.why = tidy(c.why);
    if (seen.has(c.id) || !CATS[c.cat]) console.error(`e3-cards: bad card ${c.id}`);
    seen.add(c.id);
  });

  // ---------------------------------------------------------------- the deck
  EM.lesson('e3-gymu', {
    id: 'e3-cards', order: 10, title: 'Flashcards: every Exam 3 idea', kind: 'review',
    sub: `${CARDS.length} cards in six piles, spaced repetition`,
    steps: [
      R(md`
        Read the card, say the answer out loud (or type it, where there is a box: it accepts any equivalent form), then show the answer and grade yourself honestly. Every answer has a "why": the first-principles reason, so a card you miss teaches you something.

        The six piles at the top are six kinds of question: what a thing is; a derivation in three lines; the formulas to carry (each card says whether the formula sheet has it); what changes when you change one thing; signs and directions; and numbers to know without a calculator. Tap a pile to switch it off or on.

        **Spaced repetition.** "Missed it" brings the card back a few cards later. "Got it" twice in a row, across rounds, marks it known. Each round deals only the cards you do not know yet, least known first. Your progress stays in this browser. Ten minutes a day beats an hour the night before.
      `),
      C.W('<div class="fc-host"></div>', (el) => E3Drill.cards(el.querySelector('.fc-host'), CARDS, CATS)),
      R(md`Prefer to read them, or print them? [Every card with its answer, on one page](#/l/e3-cards-list).`),
    ],
  });

  // ---------------------------------------------------------------- the same deck as one page
  const head = (t) => (/[.?!…]$/.test(t) ? t : `${t}.`);
  const block = (label, s) => (/^\$\$/.test(s) ? `**${label}**${BR}${s}` : `**${label}** ${s}`);
  const listMd = [
    md`Every flashcard, grouped by pile, with its answer and its reason. Read it straight through, or print it. To drill with spaced repetition, use [the flashcards](#/l/e3-cards).`,
    ...Object.keys(CATS).map((k) => {
      const cs = CARDS.filter((c) => c.cat === k);
      return `## ${LONG[k]} (${cs.length})${BR}` + cs.map((c) => [
        `### ${head(c.t)}`,
        c.figHtml ? `[[fig:${c.id}]]` : '',
        c.q,
        block('Answer.', c.a),
        block('Why:', c.why),
      ].filter(Boolean).join(BR)).join(BR);
    }),
  ].join(BR);
  const listFigs = {};
  CARDS.forEach((c) => { if (c.figHtml) listFigs[c.id] = { svg: c.figHtml }; });

  EM.lesson('e3-gymu', {
    id: 'e3-cards-list', order: 11, hideHome: true, title: 'Every flashcard, answers showing', kind: 'read',
    sub: `All ${CARDS.length} cards on one page, for reading and printing`,
    steps: [RF(listMd, listFigs)],
  });

  window.E3CARDS = { CARDS, CATS };
})();
